    case 'COUNTDOWN':
      countdownElapsed += dt;
      if (countdownElapsed >= 3.0) { hideCountdown(); state='PLAYING'; /* fall through to advance simTime by dt*speed */ simTime = Math.min(DURATION, simTime + dt*playbackSpeed); }
