  canvas: canvas, antialias: true, alpha: true, powerPreference: 'high-performance'
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.setSize(window.innerWidth, window.innerHeight, false);
renderer.outputEncoding = THREE.sRGBEncoding;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 0.95;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.setClearColor(0x06080d, 1);

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x141b26, 0.00215);

const camera = new THREE.PerspectiveCamera(35, window.innerWidth / window.innerHeight, 0.1, 3000);
camera.position.set(-34, 2.6, 0);

window.addEventListener('resize', function () {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight, false);
});

/* ------------------------------------------------------------------ *
 * 5. Procedural texture factory (all canvases stay detached in memory)
 * ------------------------------------------------------------------ */
function cv(w, h) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  return { c: c, x: c.getContext('2d') };
}
function tex(canvas, repeatX, repeatY, srgb) {
  const t = new THREE.CanvasTexture(canvas);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  if (repeatX) t.repeat.set(repeatX, repeatY || repeatX);
  t.anisotropy = renderer.capabilities.getMaxAnisotropy();
  if (srgb) t.encoding = THREE.sRGBEncoding;
  return t;
}

/* asphalt: damp grain + tar patches */
function asphaltTexture() {
  const o = cv(512, 512), x = o.x;
  x.fillStyle = '#14161b'; x.fillRect(0, 0, 512, 512);
  const img = x.getImageData(0, 0, 512, 512), d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (rngSim() - 0.5) * 34;
    d[i] = clamp(d[i] + n, 0, 255);
    d[i + 1] = clamp(d[i + 1] + n, 0, 255);
    d[i + 2] = clamp(d[i + 2] + n * 1.1, 0, 255);
  }
  x.putImageData(img, 0, 0);
  for (let i = 0; i < 90; i++) {
    const px = rngSim() * 512, py = rngSim() * 512, r = 8 + rngSim() * 54;
    const g = x.createRadialGradient(px, py, 0, px, py, r);
    const a = 0.05 + rngSim() * 0.09;
    g.addColorStop(0, 'rgba(60,64,72,' + a.toFixed(3) + ')');
    g.addColorStop(1, 'rgba(60,64,72,0)');
    x.fillStyle = g; x.beginPath(); x.arc(px, py, r, 0, TAU); x.fill();
  }
  for (let i = 0; i < 26; i++) {
    x.strokeStyle = 'rgba(8,9,12,' + (0.10 + rngSim() * 0.2).toFixed(3) + ')';
    x.lineWidth = 1 + rngSim() * 2.4;
    x.beginPath();
    let px = rngSim() * 512, py = rngSim() * 512;
    x.moveTo(px, py);
    for (let k = 0; k < 5; k++) { px += (rngSim() - 0.5) * 120; py += (rngSim() - 0.5) * 120; x.lineTo(px, py); }
    x.stroke();
  }
  return o.c;
}
/* wet roughness variation: elongated streaks along the driving direction */
function asphaltRoughTexture() {
  const o = cv(256, 256), x = o.x;
  x.fillStyle = '#4a4a4a'; x.fillRect(0, 0, 256, 256);
  for (let i = 0; i < 150; i++) {
    const px = rngSim() * 256, py = rngSim() * 256, w = 2 + rngSim() * 12, h = 20 + rngSim() * 90;
    const g = x.createLinearGradient(px, py, px, py + h);
    const v = Math.floor(20 + rngSim() * 70);
    g.addColorStop(0, 'rgba(' + v + ',' + v + ',' + v + ',0.55)');
    g.addColorStop(1, 'rgba(' + v + ',' + v + ',' + v + ',0)');
    x.fillStyle = g; x.fillRect(px, py, w, h);
  }
  const img = x.getImageData(0, 0, 256, 256), d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (rngSim() - 0.5) * 26;
    d[i] = clamp(d[i] + n, 0, 255); d[i + 1] = clamp(d[i + 1] + n, 0, 255); d[i + 2] = clamp(d[i + 2] + n, 0, 255);
  }
  x.putImageData(img, 0, 0);
  return o.c;
}
/* carbon fibre twill */
function carbonTexture() {
  const o = cv(256, 256), x = o.x;
  x.fillStyle = '#0c0d10'; x.fillRect(0, 0, 256, 256);
  const cell = 16;
  for (let gy = 0; gy < 256 / cell; gy++) {
    for (let gx = 0; gx < 256 / cell; gx++) {
      const up = ((gx + gy) & 1) === 0;
      const g = x.createLinearGradient(gx * cell, gy * cell,
        up ? (gx + 1) * cell : gx * cell, up ? gy * cell : (gy + 1) * cell);
      g.addColorStop(0, '#101319');
      g.addColorStop(0.5, up ? '#333a45' : '#242a33');
      g.addColorStop(1, '#0c0d10');
      x.fillStyle = g;
      x.fillRect(gx * cell, gy * cell, cell, cell);
    }
  }
  const img = x.getImageData(0, 0, 256, 256), d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (rngSim() - 0.5) * 16;
    d[i] = clamp(d[i] + n, 0, 255); d[i + 1] = clamp(d[i + 1] + n, 0, 255); d[i + 2] = clamp(d[i + 2] + n, 0, 255);
  }
  x.putImageData(img, 0, 0);
  return o.c;
}
/* tyre sidewall: plain colour band, no lettering */
function tyreTexture(band) {
  const o = cv(64, 128), x = o.x;
  x.fillStyle = '#101013'; x.fillRect(0, 0, 64, 128);
  x.fillStyle = band;
  x.fillRect(0, 44, 64, 12);
  x.fillStyle = 'rgba(255,255,255,0.05)';
  x.fillRect(0, 44, 64, 3);
  const img = x.getImageData(0, 0, 64, 128), d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (rngSim() - 0.5) * 14;
    d[i] = clamp(d[i] + n, 0, 255); d[i + 1] = clamp(d[i + 1] + n, 0, 255); d[i + 2] = clamp(d[i + 2] + n, 0, 255);
  }
  x.putImageData(img, 0, 0);
  return o.c;
}
/* car number + stripes decal */
function numberTexture(num, fg, bg) {
  const o = cv(256, 256), x = o.x;
  x.clearRect(0, 0, 256, 256);
  x.fillStyle = bg;
  x.globalAlpha = 0.92;
  x.fillRect(18, 40, 220, 176);
  x.globalAlpha = 1;
  x.fillStyle = fg;
  x.font = 'bold 148px ' + '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif';
  x.textAlign = 'center'; x.textBaseline = 'middle';
  x.fillText(String(num), 128, 132);
  x.strokeStyle = 'rgba(0,0,0,0.35)'; x.lineWidth = 6;
  x.strokeText(String(num), 128, 132);
  return o.c;
}
/* chequered start/finish */
function chequerTexture() {
  const o = cv(256, 64), x = o.x;
  for (let i = 0; i < 16; i++) {
    for (let j = 0; j < 4; j++) {
      x.fillStyle = ((i + j) & 1) ? '#e8e8e8' : '#101216';
      x.fillRect(i * 16, j * 16, 16, 16);
    }
  }
  const img = x.getImageData(0, 0, 256, 64), d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (rngSim() - 0.5) * 22;
    d[i] = clamp(d[i] + n, 0, 255); d[i + 1] = clamp(d[i + 1] + n, 0, 255); d[i + 2] = clamp(d[i + 2] + n, 0, 255);
  }
  x.putImageData(img, 0, 0);
  return o.c;
}
/* galvanised chain-link fence (alpha) */
function fenceTexture() {
  const o = cv(128, 128), x = o.x;
  x.clearRect(0, 0, 128, 128);
  x.strokeStyle = 'rgba(168,176,188,0.85)';
  x.lineWidth = 3.2;
  for (let i = -128; i < 256; i += 16) {
    x.beginPath(); x.moveTo(i, 0); x.lineTo(i + 128, 128); x.stroke();
    x.beginPath(); x.moveTo(i, 128); x.lineTo(i + 128, 0); x.stroke();
  }
  return o.c;
}
/* painted steel barrier */
function barrierTexture() {
  const o = cv(256, 64), x = o.x;
  x.fillStyle = '#b9bcc4'; x.fillRect(0, 0, 256, 64);
  for (let i = 0; i < 320; i++) {
    x.fillStyle = 'rgba(' + Math.floor(120 + rngSim() * 110) + ',' + Math.floor(122 + rngSim() * 110) + ',' + Math.floor(128 + rngSim() * 110) + ',0.5)';
    x.fillRect(rngSim() * 256, rngSim() * 64, 1 + rngSim() * 3, 1 + rngSim() * 2);
  }
  x.fillStyle = 'rgba(30,32,38,0.85)';
  x.fillRect(0, 40, 256, 6);
  x.fillStyle = 'rgba(210,60,60,0.55)';
  x.fillRect(0, 46, 256, 4);
  return o.c;
}
/* grandstand crowd speckle */
function crowdTexture() {
  const o = cv(512, 256), x = o.x;
  x.fillStyle = '#0a0b10'; x.fillRect(0, 0, 512, 256);
  const cols = ['#2a3040', '#3a2a34', '#22303a', '#3c3a2e', '#2c2c3c', '#40302a', '#1f2a36'];
  for (let i = 0; i < 2600; i++) {
    x.fillStyle = cols[Math.floor(rngSim() * cols.length)];
    const px = rngSim() * 512, py = 40 + rngSim() * 216;
    x.beginPath(); x.arc(px, py, 1.6 + rngSim() * 2.6, 0, TAU); x.fill();
  }
  return o.c;
}
/* soft radial sprite (lamp glow / particles) */
function radialSprite(inner, outer, size) {
  const o = cv(size || 128, size || 128), x = o.x;
  const g = x.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, inner);
  g.addColorStop(0.35, outer);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  x.fillStyle = g; x.fillRect(0, 0, size, size);
  return o.c;
}
/* soft puff sprite for smoke */
function puffSprite() {
  const o = cv(128, 128), x = o.x;
  x.clearRect(0, 0, 128, 128);
  for (let i = 0; i < 16; i++) {
    const px = 64 + (rngSim() - 0.5) * 42, py = 64 + (rngSim() - 0.5) * 42, r = 16 + rngSim() * 30;
    const g = x.createRadialGradient(px, py, 0, px, py, r);
    g.addColorStop(0, 'rgba(255,255,255,0.30)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    x.fillStyle = g; x.beginPath(); x.arc(px, py, r, 0, TAU); x.fill();
  }
  return o.c;
}
/* equirectangular night sky */
function skyTexture() {
  const W = 2048, H = 1024;
  const o = cv(W, H), x = o.x;
  const g = x.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0.00, '#04060c');
  g.addColorStop(0.38, '#060a14');
  g.addColorStop(0.50, '#0b1220');
  g.addColorStop(0.56, '#0a0f1a');
  g.addColorStop(1.00, '#05070c');
  x.fillStyle = g; x.fillRect(0, 0, W, H);
  /* stars */
  for (let i = 0; i < 1400; i++) {
    const px = rngSim() * W;
    const py = Math.pow(rngSim(), 1.5) * H * 0.52;
    const a = (0.12 + rngSim() * 0.85) * (1 - py / (H * 0.55));
    const s = rngSim() < 0.06 ? 2.2 : 1.0;
    x.fillStyle = 'rgba(' + Math.floor(200 + rngSim() * 55) + ',' + Math.floor(210 + rngSim() * 45) + ',' + 255,' + a.toFixed(3) + ')';
    x.beginPath(); x.arc(px, py, s, 0, TAU); x.fill();
  }
  /* milky band */
  for (let i = 0; i < 900; i++) {
    const t = rngSim();
    const px = t * W;
    const py = H * (0.20 + 0.13 * Math.sin(t * 6.0)) + (rngSim() - 0.5) * H * 0.10;
    x.fillStyle = 'rgba(150,170,220,' + (0.03 + rngSim() * 0.07).toFixed(3) + ')';
    x.beginPath(); x.arc(px, py, 1 + rngSim() * 3, 0, TAU); x.fill();
  }
  /* moon with halo */
  const mx = W * 0.68, my = H * 0.20, mr = 26;
  const halo = x.createRadialGradient(mx, my, mr * 0.6, mx, my, mr * 11);
  halo.addColorStop(0, 'rgba(196,214,255,0.30)');
  halo.addColorStop(0.35, 'rgba(160,185,240,0.09)');
  halo.addColorStop(1, 'rgba(120,150,220,0)');
  x.fillStyle = halo; x.beginPath(); x.arc(mx, my, mr * 11, 0, TAU); x.fill();
  const disc = x.createRadialGradient(mx - 8, my - 8, 1, mx, my, mr);
  disc.addColorStop(0, '#ffffff');
  disc.addColorStop(0.7, '#e8eeff');
  disc.addColorStop(1, '#b9c6e6');
  x.fillStyle = disc; x.beginPath(); x.arc(mx, my, mr, 0, TAU); x.fill();
  x.fillStyle = 'rgba(150,160,190,0.35)';
  for (let i = 0; i < 7; i++) {
    x.beginPath();
    x.arc(mx + (rngSim() - 0.5) * mr * 1.1, my + (rngSim() - 0.5) * mr * 1.1, 2 + rngSim() * 5, 0, TAU);
    x.fill();
  }
  /* faint warm city glow on one horizon */
  const cg = x.createRadialGradient(W * 0.22, H * 0.53, 10, W * 0.22, H * 0.53, W * 0.30);
  cg.addColorStop(0, 'rgba(120,78,42,0.42)');
  cg.addColorStop(0.4, 'rgba(88,58,34,0.16)');
  cg.addColorStop(1, 'rgba(60,40,24,0)');
  x.fillStyle = cg; x.fillRect(0, H * 0.30, W, H * 0.45);
  return o.c;
}

/* ------------------------------------------------------------------ *
 * 6. Sky background + image-based lighting (PMREM)
 * ------------------------------------------------------------------ */
const skyTex = tex(skyTexture(), 0, 0, true);
skyTex.wrapS = skyTex.wrapT = THREE.ClampToEdgeWrapping;
skyTex.mapping = THREE.EquirectangularReflectionMapping;
scene.background = skyTex;

const envScene = new THREE.Scene();
{
  const skyGeo = new THREE.SphereGeometry(120, 32, 20);
  const skyMat = new THREE.MeshBasicMaterial({ map: skyTex, side: THREE.BackSide });
  envScene.add(new THREE.Mesh(skyGeo, skyMat));
  /* bright floodlight panels give the paint crisp night reflections */
  const panelGeo = new THREE.PlaneGeometry(14, 5);
  const panelMat = new THREE.MeshBasicMaterial({ color: 0xdfe9ff });
  const panelMat2 = new THREE.MeshBasicMaterial({ color: 0xffe8c8 });
  const seeds = [
    [60, 40, 0, 0.6, 0], [-70, 46, 30, 1.1, 0.2], [10, 52, -80, 0.5, 2.4],
    [80, 34, 70, 0.9, 3.6], [-40, 50, -30, 0.7, 5.0], [30, 44, 110, 0.8, 1.2]
  ];
  for (let i = 0; i < seeds.length; i++) {
    const s = seeds[i];
    const m = new THREE.Mesh(panelGeo, i % 2 ? panelMat : panelMat2);
    m.position.set(s[0], s[1], s[2]);
    m.lookAt(0, 0, 0);
    m.scale.setScalar(s[3]);
    envScene.add(m);
  }
  const groundGeo = new THREE.SphereGeometry(118, 24, 12, 0, TAU, Math.PI / 2, Math.PI / 2);
  envScene.add(new THREE.Mesh(groundGeo, new THREE.MeshBasicMaterial({ color: 0x0a0d13, side: THREE.BackSide })));
}
const pmrem = new THREE.PMREMGenerator(renderer);
pmrem.compileEquirectangularShader();
const envRT = pmrem.fromScene(envScene, 0.03, 0.1, 500);
scene.environment = envRT.texture;
pmrem.dispose();

