  const g = wall;
  const pos = g.getAttribute('position'), idx = g.getIndex();
  const p2 = [], n2 = [], u2 = [];
  for (let i = 0; i < pos.count; i += 2) {
    const ax = pos.getX(i), ay = pos.getY(i), az = pos.getZ(i);
    const bx = pos.getX(i + 1), by = pos.getY(i + 1), bz = pos.getZ(i + 1);
    p2.push(ax, ay - 1.0, az, bx, by - 1.0, bz, ax, ay, az, bx, by, bz);
    const nx = side * Math.cos(0), ny = 0, nz = 0;
    n2.push(-side, 0, 0, -side, 0, 0, -side, 0, 0, -side, 0, 0);
    const v = (i / 2) / 900;
    u2.push(0, v, 1, v, 0, v, 1, v);
  }
  const idx2 = [];
  const nseg = pos.count / 2;
  for (let i = 0; i < nseg - 1; i++) {
    const a = i * 4;
    idx2.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
    idx2.push(a + 2, a + 1, a, a + 2, a + 3, a + 1);
  }
  const gg = new THREE.BufferGeometry();
  gg.setAttribute('position', new THREE.Float32BufferAttribute(p2, 3));
  gg.setAttribute('normal', new THREE.Float32BufferAttribute(n2, 3));
  gg.setAttribute('uv', new THREE.Float32BufferAttribute(u2, 2));
  gg.setIndex(idx2);
  const m = new THREE.Mesh(gg, matBarrier);
  m.receiveShadow = true;
  scene.add(m);

  /* catch fence above the barrier */
  const fg = ribbon({ steps: 900, inner: side * 9.0, outer: side * 9.05, y: () => 4.3 });
  const fp = fg.getAttribute('position'), fidx = fg.getIndex();
  const fp2 = [], fn2 = [], fu2 = [];
  for (let i = 0; i < fp.count; i += 2) {
    fp2.push(fp.getX(i), fp.getY(i) - 3.2, fp.getZ(i), fp.getX(i + 1), fp.getY(i + 1) - 3.2, fp.getZ(i + 1),
             fp.getX(i), fp.getY(i), fp.getZ(i), fp.getX(i + 1), fp.getY(i + 1), fp.getZ(i + 1));
    fn2.push(-side, 0, 0, -side, 0, 0, -side, 0, 0, -side, 0, 0);
    const v = (i / 2) / 900;
    fu2.push(0, v, 1, v, 0, v, 1, v);
  }
  const fidx2 = [];
  const fseg = fp.count / 2;
  for (let i = 0; i < fseg - 1; i++) {
    const a = i * 4;
    fidx2.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
    fidx2.push(a + 2, a + 1, a, a + 2, a + 3, a + 1);
  }
  const fgg = new THREE.BufferGeometry();
  fgg.setAttribute('position', new THREE.Float32BufferAttribute(fp2, 3));
  fgg.setAttribute('normal', new THREE.Float32BufferAttribute(fn2, 3));
  fgg.setAttribute('uv', new THREE.Float32BufferAttribute(fu2, 2));
  fgg.setIndex(fidx2);
  scene.add(new THREE.Mesh(fgg, matFence));
}

