+    pod.add(housing);
+    const lensMat = new THREE.MeshBasicMaterial({ color: 0x2a0608 });
+    const lens = new THREE.Mesh(new THREE.CircleGeometry(0.34, 20), lensMat);
+    lens.position.set(-0.22, 0.05, 0);
+    lens.rotation.y = -Math.PI / 2;
+    pod.add(lens);
