+    const repMat = new THREE.MeshBasicMaterial({ color: 0x2a0608 });
+    const rep = new THREE.Mesh(new THREE.CircleGeometry(0.17, 16), repMat);
+    rep.position.set(0.23, 0.05, 0);
+    rep.rotation.y = Math.PI / 2;
+    pod.add(rep);
+    const g = new THREE.Sprite(new THREE.SpriteMaterial({
