+/* ------------------------------------------------------------------ *
+ * 12. Pit wall (+Z side) and grandstand (−Z side) of the main straight
+ * ------------------------------------------------------------------ */
+{
+  const matPit = new THREE.MeshStandardMaterial({ color: 0x9ea3ac, roughness: 0.62, metalness: 0.2 });
+  const wall = new THREE.Mesh(new THREE.BoxGeometry(176, 1.15, 0.35), matPit);
+  wall.position.set(96, 0.6, 11.6);
+  wall.castShadow = true; wall.receiveShadow = true;
+  scene.add(wall);
+  const cap = new THREE.Mesh(new THREE.BoxGeometry(176, 0.12, 0.45),
