+    l.position.set(14 + i * 18, 1.05, 11.4);
+    l.rotation.y = Math.PI;
+    scene.add(l);
+  }
+}
+{
+  /* grandstand: stepped tiers facing the track */
+  const stand = new THREE.Group();
+  const crowd = tex(crowdTexture(), 6, 2, true);
+  const matSeat = new THREE.MeshStandardMaterial({ map: crowd, roughness: 0.9, metalness: 0.0, color: 0x8a8f99 });
+  const matCrowdGlow = new THREE.MeshBasicMaterial({ map: crowd, transparent: true, opacity: 0.30, blending: THREE.AdditiveBlending, depthWrite: false });
+  const matStruct = new THREE.MeshStandardMaterial({ color: 0x1a1d23, roughness: 0.85, metalness: 0.15 });
+  for (let i = 0; i < 12; i++) {
+    const y = 0.9 + i * 0.95, z = -26 - i * 2.1;
+    const tier = new THREE.Mesh(new THREE.BoxGeometry(150, 0.95, 2.1), matSeat);
+    tier.position.set(98, y, z);
+    tier.receiveShadow = true;
+    stand.add(tier);
+    const riser = new THREE.Mesh(new THREE.BoxGeometry(150, 0.95, 0.12), matStruct);
+    riser.position.set(98, y - 0.47, z + 1.02);
+    stand.add(riser);
+  }
+  const glowPlane = new THREE.Mesh(new THREE.PlaneGeometry(150, 26), matCrowdGlow);
+  glowPlane.position.set(98, 12, -24.9);
+  stand.add(glowPlane);
+  /* roof */
+  const roof = new THREE.Mesh(new THREE.BoxGeometry(156, 0.5, 27), matStruct);
+  roof.position.set(98, 25.4, -38);
+  roof.rotation.x = 0.06;
+  stand.add(roof);
+  for (let i = 0; i < 6; i++) {
+    const col = new THREE.Mesh(new THREE.BoxGeometry(0.7, 25, 0.7), matStruct);
+    col.position.set(26 + i * 29, 12.5, -25.5);
+    stand.add(col);
+  }
+  /* floodlit strip along the roof edge */
+  for (let i = 0; i < 16; i++) {
+    const l = new THREE.Mesh(new THREE.PlaneGeometry(6, 0.3), matLamp);
+    l.position.set(24 + i * 9.6, 24.9, -24.6);
+    l.rotation.x = 0.5;
+    stand.add(l);
+  }
+  scene.add(stand);
+}
+
+/* ------------------------------------------------------------------ *
+ * 13. Terrain: follows the road elevation, rolls away into dark hills
+ * ------------------------------------------------------------------ */
+{
+  /* coarse track sample for nearest-point queries */
+  const NS = 420;
+  const sp = [];
+  for (let i = 0; i < NS; i++) {
+    const p = C(i / NS * L, new THREE.Vector3());
+    sp.push(p.x, p.z, p.y);
+  }
+  const hillNoise = (x, z) => {
+    let h = 0, a = 1, f = 0.0032;
+    for (let o = 0; o < 5; o++) {
+      h += a * (Math.sin(x * f * 1.7 + o * 2.1) * Math.cos(z * f * 1.3 + o * 1.7)
+              + 0.6 * Math.sin((x + z) * f * 2.6 + o * 3.3));
+      a *= 0.52; f *= 2.15;
+    }
+    return h;
+  };
+  const TER = 1500, GN = 90;
+  const pos = [], idx = [];
+  for (let j = 0; j <= GN; j++) {
+    for (let i = 0; i <= GN; i++) {
+      const x = -TER / 2 + TER * i / GN, z = -TER / 2 + TER * j / GN;
+      let best = 1e18, by = 0;
+      for (let k = 0; k < NS; k++) {
+        const dx = x - sp[k * 3], dz = z - sp[k * 3 + 1];
+        const d2 = dx * dx + dz * dz;
+        if (d2 < best) { best = d2; by = sp[k * 3 + 2]; }
+      }
+      const dist = Math.sqrt(best);
+      const near = smoothstep(34, 130, dist);
+      const h = by * (1 - near) + (by + hillNoise(x, z) * 26 + 6) * near;
+      pos.push(x, h - 0.35, z);
+    }
+  }
+  for (let j = 0; j < GN; j++) {
+    for (let i = 0; i < GN; i++) {
+      const a = j * (GN + 1) + i;
+      idx.push(a, a + GN + 1, a + 1, a + 1, a + GN + 1, a + GN + 2);
+    }
+  }
+  const g = new THREE.BufferGeometry();
+  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
+  g.setIndex(idx);
+  g.computeVertexNormals();
+  const matTerrain = new THREE.MeshStandardMaterial({ color: 0x0d1016, roughness: 1.0, metalness: 0.0 });
+  const terrain = new THREE.Mesh(g, matTerrain);
+  terrain.receiveShadow = true;
+  scene.add(terrain);
+
+  /* distant hill silhouettes */
+  const matHill = new THREE.MeshStandardMaterial({ color: 0x090c12, roughness: 1, metalness: 0 });
+  for (let i = 0; i < 11; i++) {
+    const a = rngSim() * TAU;
+    const r = 900 + rngSim() * 400;
+    const hgt = 60 + rngSim() * 110;
+    const cone = new THREE.Mesh(new THREE.ConeGeometry(120 + rngSim() * 220, hgt, 7), matHill);
+    cone.position.set(Math.cos(a) * r, hgt / 2 - 12, Math.sin(a) * r);
+    cone.rotation.y = rngSim() * TAU;
+    scene.add(cone);
+  }
+}
+
+/*__PART5__*/
 })();
 </script>
