    pod.add(rep);
    const g = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTex, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true,
      color: 0xff3020, opacity: 0, fog: false
    }));
    g.scale.set(2.6, 2.6, 1);
