    spin.add(tyre);
    const barrelG = new THREE.CylinderGeometry(0.255, 0.255, W - 0.05, 22, 1, true);
    barrelG.rotateX(Math.PI / 2);
    const barrel = new THREE.Mesh(barrelG, matRim);
    barrel.material.side = THREE.DoubleSide;
    spin.add(barrel);
    const faceG = new THREE.RingGeometry(0.075, 0.255, 22, 1);
    faceG.rotateY(Math.PI / 2);
    const face = new THREE.Mesh(faceG, matRim);
    face.position.x = sgn * (W / 2 - 0.035);
    face.rotation.y = sgn > 0 ? 0 : Math.PI;
    spin.add(face);
    const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.065, 0.09, 14), matRim);
    hub.rotation.z = Math.PI / 2;
    hub.position.x = sgn * (W / 2 - 0.03);
    spin.add(hub);
    if (isFront) {
      for (let i = 0; i < 5; i++) {
