    disc.rotation.z = Math.PI / 2;
    disc.position.x = -sgn * 0.02;
    spin.add(disc);
    steer.add(spin);
    grp.add(steer);
    wheels.push({ steer: steer, spin: spin, disc: disc, isFront: isFront, sgn: sgn });
    /* brake disc glow material is shared; keep a reference */
    return wheels[wheels.length - 1];
  };
  corner(0, 1, true); corner(0, -1, true);
  corner(0, 1, false); corner(0, -1, false);

  /* ---- numbers and stripes (canvas decals) ---- */
  const decalTex = tex(numberTexture(cfg.number, cfg.accent, cfg.paint), 1, 1, true);
