/* ------------------------------------------------------------------ *
 * 19. Deterministic car state + pose
 * ------------------------------------------------------------------ */
const _p = new THREE.Vector3(), _n = new THREE.Vector3(), _t = new THREE.Vector3();
const _right = new THREE.Vector3(), _up = new THREE.Vector3(), _fwd = new THREE.Vector3();
const _m = new THREE.Matrix4(), _q = new THREE.Quaternion(), _q2 = new THREE.Quaternion();
const _e = new THREE.Euler();

function carKinematics(splineS, splineD, time) {
  const si = splineS.eval(time), di = splineD.eval(time);
  const s = si.v, d = di.v;
  C(s, _p); N(s, _n); T(s, _t);
  const pos = _p.clone().addScaledVector(_n, d);
  const fwd = _t.clone();
  const right = new THREE.Vector3().crossVectors(fwd, UP).normalize();
  const up = new THREE.Vector3().crossVectors(right, fwd).normalize();
  return {
    s: s, d: d, pos: pos, fwd: fwd, right: right, up: up,
    v: si.d, a: si.dd, dv: di.d, sgn: Math.sign(si.dd)
  };
}
function poseCar(car, kin, extra) {
  /* gradient + accel pitch + corner roll */
  const pitch = clamp(kin.a * 0.0095, -0.085, 0.075);
  const aLat = kin.v * kin.v * curvature(kin.s);
  const roll = clamp(-aLat * 0.0021, -0.075, 0.075);
  _m.makeBasis(kin.fwd, kin.up, kin.right);
  _q.setFromRotationMatrix(_m);
  _q2.setFromAxisAngle(new THREE.Vector3(0, 0, 1), pitch);
  _q.multiply(_q2);
  _q2.setFromAxisAngle(new THREE.Vector3(1, 0, 0), roll);
  _q.multiply(_q2);
  car.position.copy(kin.pos);
  car.quaternion.copy(_q);
  /* wheels */
  const spinAngle = -(kin.s) / 0.36;
  const steerAngle = clamp(Math.atan(3.6 * curvature(kin.s)), -0.42, 0.42);
  for (const w of car.userData.wheels) {
    w.spin.rotation.z = spinAngle;
    if (w.isFront) w.steer.rotation.y = steerAngle;
  }
  car.userData.kin = kin;
  return kin;
}

/* ------------------------------------------------------------------ *
