/* ------------------------------------------------------------------ *
 * 21. Synthesized sound (Web Audio only, no files, no music)
 * ------------------------------------------------------------------ */
const AudioSys = (function () {
  const AC = window.AudioContext || window.webkitAudioContext;
  let ctx = null, master = null, comp = null, noiseBuf = null, ready = false;
  const cars = [];
  let crowd = null, hum = null, breeze = null, wind = null;
  const oneShots = [];

  function makeNoise(seconds) {
    const len = Math.floor(ctx.sampleRate * seconds);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = rngAudio() * 2 - 1;
    return buf;
  }
  function noiseSource() {
    const s = ctx.createBufferSource();
    s.buffer = noiseBuf; s.loop = true;
    s.start(0);
    return s;
  }
  function panner() {
    const p = ctx.createPanner();
    p.panningModel = 'HRTF';
    p.distanceModel = 'inverse';
    p.refDistance = 7; p.maxDistance = 400; p.rolloffFactor = 1.05;
    return p;
  }
  function buildCarVoice(distinct) {
    const pan = panner();
    const cockpit = ctx.createBiquadFilter();
    cockpit.type = 'lowpass'; cockpit.frequency.value = 20000; cockpit.Q.value = 0.6;
    const gain = ctx.createGain(); gain.gain.value = 0;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass'; filter.frequency.value = 2200; filter.Q.value = 0.9;
    filter.connect(cockpit); cockpit.connect(gain); gain.connect(pan); pan.connect(master);

    const oscA = ctx.createOscillator(); oscA.type = 'sawtooth';
    const oscB = ctx.createOscillator(); oscB.type = 'square';
    const oscC = ctx.createOscillator(); oscC.type = 'triangle';
    const gA = ctx.createGain(); gA.gain.value = 0.55;
    const gB = ctx.createGain(); gB.gain.value = distinct ? 0.13 : 0.27;
    const gC = ctx.createGain(); gC.gain.value = distinct ? 0.30 : 0.16;
    oscA.connect(gA).connect(filter);
    oscB.connect(gB).connect(filter);
    oscC.connect(gC).connect(filter);
    oscA.start(0); oscB.start(0); oscC.start(0);

    /* induction / turbo layer */
    const ind = noiseSource();
    const indF = ctx.createBiquadFilter(); indF.type = 'bandpass'; indF.frequency.value = 1200; indF.Q.value = 1.3;
    const indG = ctx.createGain(); indG.gain.value = 0.12;
    ind.connect(indF).connect(indG).connect(filter);
    const turbo = ctx.createOscillator(); turbo.type = 'sine'; turbo.frequency.value = 3200;
    const turboG = ctx.createGain(); turboG.gain.value = 0.0;
    turbo.connect(turboG).connect(filter); turbo.start(0);

    /* wet-road hiss */
    const hiss = noiseSource();
    const hissF = ctx.createBiquadFilter(); hissF.type = 'highpass'; hissF.frequency.value = 2200;
    const hissG = ctx.createGain(); hissG.gain.value = 0;
    const hissPan = panner();
    hiss.connect(hissF).connect(hissG).connect(hissPan).connect(master);

    /* tyre scrub / screech */
    const scr = noiseSource();
    const scrF = ctx.createBiquadFilter(); scrF.type = 'bandpass'; scrF.frequency.value = 1500; scrF.Q.value = 5.5;
    const scrG = ctx.createGain(); scrG.gain.value = 0;
    const scrPan = panner();
    scr.connect(scrF).connect(scrG).connect(scrPan).connect(master);

    /* skid-block sparks */
    const spk = noiseSource();
    const spkF = ctx.createBiquadFilter(); spkF.type = 'bandpass'; spkF.frequency.value = 5200; spkF.Q.value = 1.6;
    const spkG = ctx.createGain(); spkG.gain.value = 0;
    const spkPan = panner();
    spk.connect(spkF).connect(spkG).connect(spkPan).connect(master);

    return {
      oscA: oscA, oscB: oscB, oscC: oscC, turbo: turbo, filter: filter,
      cockpit: cockpit, gain: gain, pan: pan, indG: indG, indF: indF, turboG: turboG,
      hissG: hissG, hissPan: hissPan, scrG: scrG, scrPan: scrPan,
      spkG: spkG, spkPan: spkPan, base: distinct ? 1.0 : 0.92
    };
  }
  function buildAmbience() {
    /* crowd at the grandstand */
    const src = noiseSource();
    const f = ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = 620; f.Q.value = 0.65;
    const g = ctx.createGain(); g.gain.value = 0.0;
    const p = panner();
    src.connect(f).connect(g).connect(p).connect(master);
    if (p.positionX) { p.positionX.value = 98; p.positionY.value = 9; p.positionZ.value = -30; }
    crowd = { g: g, f: f };

    /* floodlight electrical hum */
    const h1 = ctx.createOscillator(); h1.type = 'sine'; h1.frequency.value = 50;
    const h2 = ctx.createOscillator(); h2.type = 'sine'; h2.frequency.value = 150;
    const hg = ctx.createGain(); hg.gain.value = 0.012;
    h1.connect(hg); h2.connect(hg); hg.connect(master);
    h1.start(0); h2.start(0);
    hum = { g: hg };

    /* humid breeze */
    const b = noiseSource();
    const bf = ctx.createBiquadFilter(); bf.type = 'lowpass'; bf.frequency.value = 420;
    const bg = ctx.createGain(); bg.gain.value = 0.02;
    b.connect(bf).connect(bg).connect(master);
    breeze = { g: bg };

    /* wind roar (cockpit) */
    const w = noiseSource();
    const wf = ctx.createBiquadFilter(); wf.type = 'bandpass'; wf.frequency.value = 520; wf.Q.value = 0.5;
    const wg = ctx.createGain(); wg.gain.value = 0;
    w.connect(wf).connect(wg).connect(master);
    wind = { g: wg, f: wf };
  }
  function init() {
    if (ctx || !AC) return;
    try { ctx = new AC(); } catch (e) { return; }
    master = ctx.createGain(); master.gain.value = 0.0;
    comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -13; comp.knee.value = 20; comp.ratio.value = 6;
    comp.attack.value = 0.004; comp.release.value = 0.22;
    master.connect(comp); comp.connect(ctx.destination);
    noiseBuf = makeNoise(2.4);
    cars.push(buildCarVoice(false), buildCarVoice(true));
    buildAmbience();
    ready = true;
    if (ctx.state === 'suspended') ctx.resume();
  }
  function resume() {
    if (!ctx) init();
    if (ctx && ctx.state === 'suspended') ctx.resume();
  }
  function stopOneShots() {
    while (oneShots.length) {
      const o = oneShots.pop();
      try { o.stop(ctx.currentTime + 0.02); } catch (e) { }
    }
  }
  function oneShot(fn) {
    if (!ready) return;
    const nodes = fn(ctx.currentTime);
    if (nodes) oneShots.push(nodes);
  }
  function beep(freq, dur, vol, type) {
    oneShot(function (t0) {
      const o = ctx.createOscillator(); o.type = type || 'square'; o.frequency.value = freq;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, t0);
      g.gain.exponentialRampToValueAtTime(Math.max(vol, 0.0002), t0 + 0.008);
      g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
      o.connect(g); g.connect(master);
      o.start(t0); o.stop(t0 + dur + 0.03);
      return o;
    });
  }
  function click(vol, bright) {
    oneShot(function (t0) {
      const s = ctx.createBufferSource(); s.buffer = noiseBuf;
