    hideCountdown();
    countdownElapsed = 0; holdElapsed = 0;
    simTime = 0;
    elScrub.value = '0';
    state = 'PAUSED';
    setPlayingIcons(false);
    renderAt(0);
  } else if (state === 'PAUSED') {
    state = 'PLAYING';
    setPlayingIcons(true);
  } else if (state === 'ENDED') {
    simTime = 0;
    elScrub.value = '0';
    state = 'PLAYING';
    setPlayingIcons(true);
