/* tyre sidewall: plain colour band, no lettering */
function tyreTexture(band) {
  const o = cv(64, 128), x = o.x;
  x.fillStyle = '#101013'; x.fillRect(0, 0, 64, 128);
  x.fillStyle = band;
  x.fillRect(0, 8, 64, 15);
  x.fillStyle = 'rgba(255,255,255,0.05)';
  x.fillRect(0, 8, 64, 3);
  x.fillStyle = 'rgba(0,0,0,0.35)';
  x.fillRect(0, 23, 64, 4);
  const img = x.getImageData(0, 0, 64, 128), d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (rngSim() - 0.5) * 14;
    d[i] = clamp(d[i] + n, 0, 255); d[i + 1] = clamp(d[i + 1] + n, 0, 255); d[i + 2] = clamp(d[i + 2] + n, 0, 255);
  }
  x.putImageData(img, 0, 0);
  return o.c;
}
/* wheel rim face: spokes with openings so the brake disc shows through */
function spokeTexture() {
  const o = cv(128, 128), x = o.x;
  x.clearRect(0, 0, 128, 128);
  x.strokeStyle = '#c2c9d3'; x.lineWidth = 9;
  x.beginPath(); x.arc(64, 64, 57, 0, TAU); x.stroke();
  x.strokeStyle = '#aeb6c1'; x.lineWidth = 8;
  x.beginPath(); x.arc(64, 64, 25, 0, TAU); x.stroke();
  for (let i = 0; i < 8; i++) {
    const a = i / 8 * TAU + 0.2;
    x.strokeStyle = '#b6bdc8'; x.lineWidth = 8;
    x.beginPath();
    x.moveTo(64 + Math.cos(a) * 22, 64 + Math.sin(a) * 22);
    x.lineTo(64 + Math.cos(a) * 56, 64 + Math.sin(a) * 56);
    x.stroke();
  }
  return o.c;
}

