function oneShot(fn) {
  if (!ready) return;
  const nodes = fn(ctx.currentTime);
  if (nodes) {
    oneShots.push(nodes);
    /* retire finished one-shots so the list never grows without bound */
    setTimeout(function () {
      const i = oneShots.indexOf(nodes);
      if (i >= 0) oneShots.splice(i, 1);
    }, 4000);
  }
}

