#!/usr/bin/env python3
"""Build a debuggable copy of index.html outside the deliverable folder."""
import re, sys, pathlib

SRC = pathlib.Path("/private/tmp/pcd-sbx-minimax-m3.1-flash-2qbro9mc/work/index.html")
DST = pathlib.Path("/private/tmp/pcd-sbx-minimax-m3.1-flash-2qbro9mc/dev/debug.html")

html = SRC.read_text()

# 1. expose an internal hook for deterministic single-frame capture
hook = """
window.__dbg = function (t) {
  state = 'PAUSED';
  simTime = t;
  setPlayingIcons(false);
  elScrub.value = t.toFixed(3);
  renderAt(t);
  dump('DBG renderAt ' + t + ' ok\\n');
};
window.__diag = function () {
  var kinR = carRed.userData.kin, kinB = carBlue.userData.kin;
  dump('DIAG L=' + L.toFixed(2) + ' redS=' + kinR.s.toFixed(2) + ' blueS=' + kinB.s.toFixed(2)
    + ' redPos=' + kinR.pos.toArray().map(function (v) { return v.toFixed(1); }).join(',')
    + ' bluePos=' + kinB.pos.toArray().map(function (v) { return v.toFixed(1); }).join(',')
    + ' meshes=' + (scene.children.length)
    + ' redMeshes=' + carRed.children.length + ' blueMeshes=' + carBlue.children.length + '\\n');
};
"""
anchor = "/* ------------------------------------------------------------------ *\n * 26. Boot"
assert anchor in html
html = html.replace(anchor, hook + anchor)

# 2. error + log dumping
inject = """
<script>
window.__errs = [];
window.addEventListener('error', function (e) {
  window.__errs.push(e.message + ' @' + e.lineno + ':' + e.colno);
  try { dump('PAGE-ERROR: ' + e.message + ' @' + e.lineno + ':' + e.colno + '\\n'); } catch (x) {}
});
(function () {
  var oe = console.error;
  console.error = function () {
    try { dump('CONSOLE-ERROR: ' + Array.prototype.join.call(arguments, ' ') + '\\n'); } catch (x) {}
    oe.apply(console, arguments);
  };
})();
</script>
"""
html = html.replace("</body>", inject + "</body>")

# 3. run a diagnostic + requested frame once the script has booted
boot_extra = """
(function () {
  try {
    var m = /[?&]t=([0-9.]+)/.exec(location.search);
    if (m) window.__dbg(parseFloat(m[1]));
    if (window.__diag) window.__diag();
  } catch (e) { try { dump('BOOT-ERROR: ' + e.message + '\\n'); } catch (x) {} }
})();
"""
html = html.replace("</script>\n</body>", boot_extra + "</script>\n</body>")

DST.write_text(html)
print("wrote", DST, len(html), "bytes")

