/* =========================================================================
   Headless verification harness.
   Runs the real application script in JavaScriptCore (osascript -l JavaScript)
   against a faithful-enough Three.js stub, then asserts on simulation math.
   ========================================================================= */

var OUT = [];
function say(s) { OUT.push(String(s)); }

/* ---------- generic auto-mock ---------- */
function mock(tag) {
  var t = function () { return mock(tag + '()'); };
  t.__props = {};
  return new Proxy(t, {
    get: function (target, prop) {
      if (prop === 'then' || prop === Symbol.toPrimitive) return undefined;
      if (prop === Symbol.iterator) return undefined;
      if (typeof prop === 'symbol') return undefined;
      if (prop === 'count') return 0;
      if (prop === 'length') return 0;
      if (!(prop in target.__props)) target.__props[prop] = mock(tag + '.' + String(prop));
      return target.__props[prop];
    },
    set: function (target, prop, v) { target.__props[prop] = v; return true; },
    apply: function () { return mock(tag + '()'); },
    construct: function () { return mock('new ' + tag); },
    has: function () { return true; }
  });
}

/* ---------- real math classes ---------- */
function V3(x, y, z) { this.x = x || 0; this.y = y || 0; this.z = z || 0; }
V3.prototype = {
  set: function (x, y, z) { this.x = x; this.y = y; this.z = z; return this; },
  copy: function (v) { this.x = v.x; this.y = v.y; this.z = v.z; return this; },
  clone: function () { return new V3(this.x, this.y, this.z); },
  add: function (v) { this.x += v.x; this.y += v.y; this.z += v.z; return this; },
