/* =========================================================================
   Assertions run against the live application internals.
   ========================================================================= */
var FAILS = [];
function check(name, cond, detail) {
  if (cond) say('PASS  ' + name + (detail ? '  [' + detail + ']' : ''));
  else { say('FAIL  ' + name + (detail ? '  [' + detail + ']' : '')); FAILS.push(name); }
}
function near(a, b, tol) { return Math.abs(a - b) <= tol; }
function vfmt(v) { return '(' + v.x.toFixed(2) + ', ' + v.y.toFixed(2) + ', ' + v.z.toFixed(2) + ')'; }

/* ---------- 1. boot ---------- */
check('app booted and exported internals', typeof window.__app === 'object');
var A = window.__app;
if (!A) { say('ABORT'); } else {

/* ---------- 2. track ---------- */
check('lap length ~1552 m', near(A.L, 1552, 6), 'L=' + A.L.toFixed(2));
var c0 = A.C(0), n0 = A.N(0), t0v = A.T(0);
check('start line at origin', near(c0.x, 0, 0.01) && near(c0.y, 0, 0.01) && near(c0.z, 0, 0.01), vfmt(c0));
check('right-hand normal at s=0 is +Z', near(n0.x, 0, 0.001) && near(n0.y, 0, 0.001) && near(n0.z, 1, 0.001), vfmt(n0));
check('tangent at s=0 is +X', near(t0v.x, 1, 0.01) && near(t0v.z, 0, 0.02), vfmt(t0v));
var cEnd = A.C(A.L);
check('centreline closes on itself', cEnd.distanceTo(c0) < 0.6, 'gap=' + cEnd.distanceTo(c0).toFixed(3));

/* ---------- 3. checkpoint table / motion ---------- */
function sOf(t, sp) { return sp.eval(t).v; }
var tFinishB = null, tFinishR = null;
for (var t = 0; t <= 40; t += 0.001) {
  if (tFinishB === null && sOf(t, A.splineB) >= A.L) tFinishB = t;
  if (tFinishR === null && sOf(t, A.splineR) >= A.L) tFinishR = t;
}
check('blue crosses the line ~36.49 s', near(tFinishB, 36.49, 0.12), 't=' + tFinishB.toFixed(3));
check('red crosses the line ~36.54 s', near(tFinishR, 36.54, 0.12), 't=' + tFinishR.toFixed(3));
check('finish margin ~3.3 m', near(sOf(tFinishB, A.splineR), A.L, 4.5), 'gap=' + (A.L - sOf(tFinishB, A.splineR)).toFixed(2) + ' m');
var tLevel = null;
for (var t2 = 30; t2 <= 40; t2 += 0.001) {
  if (sOf(t2, A.splineR) >= sOf(t2, A.splineB)) { tLevel = t2; break; }
}
check('cars draw level ~35.33 s', near(tLevel, 35.33, 0.45), 't=' + tLevel.toFixed(3));
/* speeds: derivative of the spline */
check('peak speed is realistic (45-75 m/s)', (function () {
  var mx = 0;
  for (var t3 = 0; t3 <= 40; t3 += 0.05) mx = Math.max(mx, sOf(t3, A.splineR));
  return mx > 45 && mx < 75;
})(), 'vmax=' + (function () { var mx = 0; for (var t4 = 0; t4 <= 40; t4 += 0.05) mx = Math.max(mx, sOf(t4, A.splineR)); return mx.toFixed(1); })() + ' m/s');
/* lateral offsets */
check('red and blue swap sides in the final corner', (function () {
  return A.splineDR.eval(35).v < 0 && A.splineDB.eval(35).v > 0;
})(), 'dR=' + A.splineDR.eval(35).v.toFixed(2) + ' dB=' + A.splineDB.eval(35).v.toFixed(2));

/* ---------- 4. determinism ---------- */
A.renderAt(12.5);
var snapA = {
  r: A.cars.red.position.toArray().map(function (v) { return v.toFixed(6); }).join(','),
  b: A.cars.blue.position.toArray().map(function (v) { return v.toFixed(6); }).join(','),
  rq: A.cars.red.quaternion.toArray ? '' : (A.cars.red.quaternion.x.toFixed(6) + ',' + A.cars.red.quaternion.y.toFixed(6) + ',' + A.cars.red.quaternion.z.toFixed(6) + ',' + A.cars.red.quaternion.w.toFixed(6)),
  cam: A.camera.position.toArray().map(function (v) { return v.toFixed(6); }).join(','),
  fov: A.camera.fov
};
A.renderAt(5.0);
A.renderAt(30.0);
A.renderAt(12.5);
var snapB = {
  r: A.cars.red.position.toArray().map(function (v) { return v.toFixed(6); }).join(','),
  b: A.cars.blue.position.toArray().map(function (v) { return v.toFixed(6); }).join(','),
  rq: A.cars.red.quaternion.x.toFixed(6) + ',' + A.cars.red.quaternion.y.toFixed(6) + ',' + A.cars.red.quaternion.z.toFixed(6) + ',' + A.cars.red.quaternion.w.toFixed(6),
  cam: A.camera.position.toArray().map(function (v) { return v.toFixed(6); }).join(','),
  fov: A.camera.fov
};
check('renderAt is deterministic after scrubbing', snapA.r === snapB.r && snapA.b === snapB.b && snapA.rq === snapB.rq && snapA.cam === snapB.cam && snapA.fov === snapB.fov);

/* ---------- 5. no NaNs anywhere ---------- */
var nan = false;
for (var tt = 0; tt <= 40; tt += 0.25) {
  A.renderAt(tt);
  var p = A.cars.red.position, q = A.cars.blue.position;
  if (!isFinite(p.x) || !isFinite(p.y) || !isFinite(p.z) || !isFinite(q.x) || !isFinite(q.y) || !isFinite(q.z)) { nan = true; break; }
  if (!isFinite(A.camera.position.x) || !isFinite(A.camera.position.y) || !isFinite(A.camera.position.z)) { nan = true; break; }
}
check('no NaN in poses or camera over the whole timeline', !nan);

/* ---------- 6. car construction ---------- */
var rc = 0, bc = 0;
A.cars.red.traverse(function (o) { if (o.geometry) rc++; });
A.cars.blue.traverse(function (o) { if (o.geometry) bc++; });
check('red car has >= 40 shaped meshes', rc >= 40, 'meshes=' + rc);
check('blue car has >= 40 shaped meshes', bc >= 40, 'meshes=' + bc);
var hasDRS = !!A.cars.blue.userData.drs, hasRain = !!A.cars.red.userData.rain, hasDisc = !!A.cars.red.userData.discMat;
check('rear wing has a movable DRS flap', hasDRS);
check('rear crash structure carries a rain light', hasRain);
check('brake discs are separate emissive meshes', hasDisc);

/* ---------- 7. camera schedule ---------- */
function camAt(t) { A.renderAt(t); return { p: A.camera.position.clone(), fov: A.camera.fov, q: A.camera.quaternion.clone() }; }
var c2 = camAt(8);
var kinB8 = A.cars.blue.userData.kin;
var exp2 = A.C(kinB8.s - 9).clone().addScaledVector(A.N(kinB8.s), kinB8.d).add(new V3(0, 2.4, 0));
check('shot 2 chase position', near(c2.p.x, exp2.x, 0.01) && near(c2.p.y, exp2.y, 0.01) && near(c2.p.z, exp2.z, 0.01), vfmt(c2.p) + ' vs ' + vfmt(exp2));
check('shot 2 fov 50', near(c2.fov, 50, 0.001), 'fov=' + c2.fov);
var c3 = camAt(13);
var exp3 = A.C(400).clone().addScaledVector(A.N(400), -18).add(new V3(0, 5, 0));
check('shot 3 trackside position', near(c3.p.x, exp3.x, 0.01) && near(c3.p.y, exp3.y, 0.01) && near(c3.p.z, exp3.z, 0.01), vfmt(c3.p) + ' vs ' + vfmt(exp3));
check('shot 3 fov 24', near(c3.fov, 24, 0.001), 'fov=' + c3.fov);
var c4 = camAt(17);
var bluePos = A.cars.blue.position.clone();
var local = new V3(-0.55, 1.25, 0).applyQuaternion(A.cars.blue.quaternion);
var exp4 = bluePos.clone().add(local);
check('shot 4 rigid T-cam rides the blue car', near(c4.p.x, exp4.x, 0.01) && near(c4.p.y, exp4.y, 0.01) && near(c4.p.z, exp4.z, 0.01), vfmt(c4.p) + ' vs ' + vfmt(exp4));
check('shot 4 fov 75', near(c4.fov, 75, 0.001), 'fov=' + c4.fov);
var c5 = camAt(22);
var exp5 = A.C(725).clone().addScaledVector(A.N(725), 20).add(new V3(0, 3, 0));
check('shot 5 hairpin position', near(c5.p.x, exp5.x, 0.01) && near(c5.p.y, exp5.y, 0.01) && near(c5.p.z, exp5.z, 0.01), vfmt(c5.p) + ' vs ' + vfmt(exp5));
check('shot 5 fov 28', near(c5.fov, 28, 0.001), 'fov=' + c5.fov);
var c6 = camAt(27);
check('shot 6 aerial position', near(c6.p.x, -80, 0.01) && near(c6.p.y, 120, 0.01) && near(c6.p.z, 150, 0.01), vfmt(c6.p));
check('shot 6 fov 30', near(c6.fov, 30, 0.001), 'fov=' + c6.fov);
var c7 = camAt(32);
var exp7 = A.C(1300).clone().addScaledVector(A.N(1300), -12).add(new V3(0, 1.2, 0));
check('shot 7 final-corner position', near(c7.p.x, exp7.x, 0.01) && near(c7.p.y, exp7.y, 0.01) && near(c7.p.z, exp7.z, 0.01), vfmt(c7.p) + ' vs ' + vfmt(exp7));
check('shot 7 fov 30', near(c7.fov, 30, 0.001), 'fov=' + c7.fov);
var c8 = camAt(37);
check('shot 8 finish-line position', near(c8.p.x, -20, 0.01) && near(c8.p.y, 4.5, 0.01) && near(c8.p.z, 15, 0.01), vfmt(c8.p));
check('shot 8 fov 32', near(c8.fov, 32, 0.001), 'fov=' + c8.fov);
var c1 = camAt(2);
check('shot 1 grid position', near(c1.p.x, -34, 0.01) && near(c1.p.y, 2.6, 0.01) && near(c1.p.z, 0, 0.01), vfmt(c1.p));
check('shot 1 fov 35', near(c1.fov, 35, 0.001), 'fov=' + c1.fov);

/* ---------- 8. both cars stay in frame ---------- */
function inFrame(cam, p, aspect) {
  var v = p.clone().sub(cam.p);
  var q = new QT();
  q.x = -cam.q.x; q.y = -cam.q.y; q.z = -cam.q.z; q.w = cam.q.w;
  v.applyQuaternion(q);
  var depth = -v.z;
  if (depth <= 0.05) return -1;
  var vTan = Math.tan(cam.fov * Math.PI / 360);
  var hTan = vTan * aspect;
  var mx = Math.abs(v.x) / depth / hTan;
  var my = Math.abs(v.y) / depth / vTan;
  return Math.max(mx, my);   /* <= 1 means inside the frame */
}
var worst169 = 0, worstPortrait = 0, worstT = 0;
for (var ts = 0; ts <= 40; ts += 0.25) {
  var cam = camAt(ts);
  var r = inFrame(cam, A.cars.red.position, 16 / 9);
  var b = inFrame(cam, A.cars.blue.position, 16 / 9);
  var rp = inFrame(cam, A.cars.red.position, 1280 / 1340);
  var bp = inFrame(cam, A.cars.blue.position, 1280 / 1340);
  var m169 = Math.max(r, b), mp = Math.max(rp, bp);
  if (m169 > worst169) { worst169 = m169; worstT = ts; }
  if (mp > worstPortrait) worstPortrait = mp;
}
check('both cars stay in frame at 16:9', worst169 <= 1.0, 'worst=' + worst169.toFixed(3) + ' at t=' + worstT);
check('both cars stay in frame at 1280x1340 portrait', worstPortrait <= 1.0, 'worst=' + worstPortrait.toFixed(3));

