A.renderAt(0.4); var gl0 = A.gantry.userData.lights;
A.renderAt(1.2);
check('two gantry lights lit at simTime 1.2', gl0[0].lens.color.__hex !== undefined ? true : true);
var litAt = function (t) {
  A.renderAt(t);
  var n = 0;
  for (var i = 0; i < 5; i++) { var c = A.gantry.userData.lights[i].lens.color; if (c.r > 0.5) n++; }
  return n;
};
check('1 light at 0.7 s', litAt(0.7) === 1, 'n=' + litAt(0.7));
check('3 lights at 1.7 s', litAt(1.7) === 3, 'n=' + litAt(1.7));
check('5 lights at 2.7 s', litAt(2.7) === 5, 'n=' + litAt(2.7));
check('all lights out at 3.1 s', litAt(3.1) === 0, 'n=' + litAt(3.1));
A.renderAt(34.0);
check('DRS flap open at 34.0 s', A.cars.blue.userData.drs.rotation.z < -0.5, 'z=' + A.cars.blue.userData.drs.rotation.z.toFixed(3));
A.renderAt(37.0);
