check('countdown shows 3', IDS['countdown'].textContent === '3', 'text="' + IDS['countdown'].textContent + '"');
step(10, 100);
check('countdown shows 2 at 1.0 s', IDS['countdown'].textContent === '2', 'text="' + IDS['countdown'].textContent + '"');
step(10, 100);
check('countdown shows 1 at 2.0 s', IDS['countdown'].textContent === '1', 'text="' + IDS['countdown'].textContent + '"');
