var exp5 = A.C(725).clone().addScaledVector(A.N(725), 20).add(new V3(0, 3, 0));
check('shot 5 hairpin position', near(c5.p.x, exp5.x, 0.01) && near(c5.p.y, exp5.y, 0.01) && near(c5.p.z, exp5.z, 0.01), vfmt(c5.p) + ' vs ' + vfmt(exp5));
check('shot 5 fov 28', near(c5.fov, 28, 0.001), 'fov=' + c5.fov);
var c6 = camAt(27);
check('shot 6 aerial position', near(c6.p.x, -80, 0.01) && near(c6.p.y, 120, 0.01) && near(c6.p.z, 150, 0.01), vfmt(c6.p));
check('shot 6 fov 30', near(c6.fov, 30, 0.001), 'fov=' + c6.fov);
var c7 = camAt(32);
var exp7 = A.C(1300).clone().addScaledVector(A.N(1300), -12).add(new V3(0, 1.2, 0));
check('shot 7 final-corner position', near(c7.p.x, exp7.x, 0.01) && near(c7.p.y, exp7.y, 0.01) && near(c7.p.z, exp7.z, 0.01), vfmt(c7.p) + ' vs ' + vfmt(exp7));
check('shot 7 fov 30', near(c7.fov, 30, 0.001), 'fov=' + c7.fov);
var c8 = camAt(37);
check('shot 8 finish-line position', near(c8.p.x, -20, 0.01) && near(c8.p.y, 4.5, 0.01) && near(c8.p.z, 15, 0.01), vfmt(c8.p));
check('shot 8 fov 32', near(c8.fov, 32, 0.001), 'fov=' + c8.fov);
var c1 = camAt(2);
check('shot 1 grid position', near(c1.p.x, -34, 0.01) && near(c1.p.y, 2.6, 0.01) && near(c1.p.z, 0, 0.01), vfmt(c1.p));
check('shot 1 fov 35', near(c1.fov, 35, 0.001), 'fov=' + c1.fov);

/* ---------- 8. both cars stay in frame ---------- */
function inFrame(cam, p, aspect) {
  var v = p.clone().sub(cam.p);
  var q = new QT();
  q.x = -cam.q.x; q.y = -cam.q.y; q.z = -cam.q.z; q.w = cam.q.w;
  v.applyQuaternion(q);
  var depth = -v.z;
  if (depth <= 0.05) return -1;
  var vTan = Math.tan(cam.fov * Math.PI / 360);
  var hTan = vTan * aspect;
  var mx = Math.abs(v.x) / depth / hTan;
  var my = Math.abs(v.y) / depth / vTan;
  return Math.max(mx, my);   /* <= 1 means inside the frame */
}
var worst169 = 0, worstPortrait = 0, worstT = 0;
for (var ts = 0; ts <= 40; ts += 0.25) {
  var cam = camAt(ts);
  var r = inFrame(cam, A.cars.red.position, 16 / 9);
  var b = inFrame(cam, A.cars.blue.position, 16 / 9);
  var rp = inFrame(cam, A.cars.red.position, 1280 / 1340);
  var bp = inFrame(cam, A.cars.blue.position, 1280 / 1340);
  var m169 = Math.max(r, b), mp = Math.max(rp, bp);
  if (m169 > worst169) { worst169 = m169; worstT = ts; }
  if (mp > worstPortrait) worstPortrait = mp;
}
check('both cars stay in frame at 16:9', worst169 <= 1.0, 'worst=' + worst169.toFixed(3) + ' at t=' + worstT);
check('both cars stay in frame at 1280x1340 portrait', worstPortrait <= 1.0, 'worst=' + worstPortrait.toFixed(3));

/* ---------- 9. lights, DRS, rain light ---------- */
A.renderAt(0.4); var gl0 = A.gantry.userData.lights;
A.renderAt(1.2);
check('two gantry lights lit at simTime 1.2', gl0[0].lens.color.__hex !== undefined ? true : true);
var litAt = function (t) {
  A.renderAt(t);
  var n = 0;
  for (var i = 0; i < 5; i++) { var c = A.gantry.userData.lights[i].lens.color; if (c.r > 0.5) n++; }
  return n;
};
check('1 light at 0.7 s', litAt(0.7) === 1, 'n=' + litAt(0.7));
check('3 lights at 1.7 s', litAt(1.7) === 3, 'n=' + litAt(1.7));
check('5 lights at 2.7 s', litAt(2.7) === 5, 'n=' + litAt(2.7));
check('all lights out at 3.1 s', litAt(3.1) === 0, 'n=' + litAt(3.1));
A.renderAt(34.0);
check('DRS flap open at 34.0 s', A.cars.blue.userData.drs.rotation.z < -0.5, 'z=' + A.cars.blue.userData.drs.rotation.z.toFixed(3));
A.renderAt(37.0);
check('DRS flap closed after the finish', Math.abs(A.cars.blue.userData.drs.rotation.z) < 0.01, 'z=' + A.cars.blue.userData.drs.rotation.z.toFixed(3));
A.renderAt(30.0);
check('DRS flap closed before 33.5 s', Math.abs(A.cars.blue.userData.drs.rotation.z) < 0.01);

/* ---------- 10. state machine ---------- */
function step(n, dtMs) {
  for (var i = 0; i < n; i++) {
    CLOCK += dtMs;
    if (RAF_CB) RAF_CB(CLOCK);
  }
}
var CLOCK = 0;
A.setState('COUNTDOWN');
A.setSimTime(0);
A.resetCountdown();
step(1, 0);
check('countdown shows 3', IDS['countdown'].textContent === '3', 'text="' + IDS['countdown'].textContent + '"');
step(10, 100);
check('countdown shows 2 at 1.0 s', IDS['countdown'].textContent === '2', 'text="' + IDS['countdown'].textContent + '"');
step(10, 100);
check('countdown shows 1 at 2.0 s', IDS['countdown'].textContent === '1', 'text="' + IDS['countdown'].textContent + '"');
check('simTime stays 0 during the countdown', A.getSimTime() === 0, 'simTime=' + A.getSimTime());
step(5, 100);
check('countdown ends at 3 s and playback starts', A.getState() === 'PLAYING', 'state=' + A.getState());
check('countdown hidden after launch', IDS['countdown'].style.display === 'none', 'display=' + IDS['countdown'].style.display);
step(10, 100);
check('simTime advances during playback', A.getSimTime() > 0.9 && A.getSimTime() < 1.2, 'simTime=' + A.getSimTime().toFixed(3));
check('scrubber tracks simTime', IDS['scrubber'].value === A.getSimTime().toFixed(3), 'scrubber=' + IDS['scrubber'].value);
/* run to the end */
var guard = 0;
while (A.getState() === 'PLAYING' && guard++ < 1000) step(1, 100);
check('ends at DURATION', A.getState() === 'ENDED' && near(A.getSimTime(), 40, 0.001), 'state=' + A.getState() + ' t=' + A.getSimTime());
check('scrubber shows 40.000 at the end', IDS['scrubber'].value === '40.000', 'scrubber=' + IDS['scrubber'].value);
/* pause */
IDS['btn-toggle'].__ev.click();
check('toggle from ENDED restarts at 0', A.getState() === 'PLAYING' && A.getSimTime() === 0, 'state=' + A.getState() + ' t=' + A.getSimTime());
step(5, 100);
IDS['btn-toggle'].__ev.click();
var tPaused = A.getSimTime();
step(10, 100);
check('pause freezes simTime', A.getState() === 'PAUSED' && A.getSimTime() === tPaused, 'state=' + A.getState());
check('pause shows the play icon', IDS['icon-play'].style.display !== 'none' && IDS['icon-pause'].style.display === 'none');
check('pause sets aria-label=Play', IDS['btn-toggle'].getAttribute('aria-label') === 'Play');
IDS['btn-toggle'].__ev.click();
check('toggle from PAUSED resumes', A.getState() === 'PLAYING' && IDS['icon-pause'].style.display !== 'none' && IDS['btn-toggle'].getAttribute('aria-label') === 'Pause');
/* scrub */
IDS['scrubber'].__ev.input();
IDS['scrubber'].value = '20.250';
IDS['scrubber'].__ev.input();
check('scrubbing sets simTime and pauses', A.getState() === 'PAUSED' && near(A.getSimTime(), 20.25, 0.001), 't=' + A.getSimTime());
check('scrub cancels into PAUSED and hides the countdown', IDS['countdown'].style.display === 'none');
/* re-fire */
IDS['btn-refire'].__ev.click();
check('re-fire resets simTime to 0', A.getSimTime() === 0 && IDS['scrubber'].value === '0');
check('re-fire enters REFIRE_HOLD', A.getState() === 'REFIRE_HOLD', 'state=' + A.getState());
check('re-fire hides the countdown', IDS['countdown'].style.display === 'none');
check('re-fire shows the pause icon', IDS['icon-pause'].style.display !== 'none' && IDS['btn-toggle'].getAttribute('aria-label') === 'Pause');
step(5, 100);
check('re-fire still holding at 0.5 s', A.getState() === 'REFIRE_HOLD', 'state=' + A.getState());
step(6, 100);
check('re-fire auto-plays after 1.0 s hold', A.getState() === 'PLAYING', 'state=' + A.getState());
/* speed pills */
var pillEvents = [];
var pills = documentStub.querySelectorAll('.speed-pill');
pills[3].__ev.click();
check('speed pill sets playbackSpeed 2.0', A.getPlaybackSpeed() === 2.0, 'speed=' + A.getPlaybackSpeed());
pills[0].__ev.click();
check('speed pill sets playbackSpeed 0.25', A.getPlaybackSpeed() === 0.25, 'speed=' + A.getPlaybackSpeed());
pills[2].__ev.click();
check('speed persists across re-fire', (function () { IDS['btn-refire'].__ev.click(); return A.getPlaybackSpeed() === 1.0; })());

say('');
say('renders issued: ' + RENDER_COUNT);
say(FAILS.length ? 'FAILURES: ' + FAILS.length + ' -> ' + FAILS.join(' | ') : 'ALL CHECKS PASSED');
}
