#!/usr/bin/env python3
"""Scan a JS source for unbalanced braces / unterminated strings / bad tokens."""
import sys, pathlib

path = sys.argv[1]
src = pathlib.Path(path).read_text()

i = 0
n = len(src)
line = 1
stack = []
pairs = {'}': '{', ')': '(', ']': '['}
errs = []
prev_significant = ''

def err(msg, pos, ln):
    errs.append("line %d: %s  | %s" % (ln, msg, src[max(0,pos-90):pos+60].replace('\n', '\\n')))

while i < n:
    c = src[i]
    if c == '\n':
        line += 1; i += 1; continue
    if c == '/' and i + 1 < n and src[i+1] == '/':
        while i < n and src[i] != '\n':
            i += 1
        continue
    if c == '/' and i + 1 < n and src[i+1] == '*':
        start = i
        i += 2
        while i + 1 < n and not (src[i] == '*' and src[i+1] == '/'):
            if src[i] == '\n': line += 1
            i += 1
        i += 2
        continue
    if c in '"\'':
        q = c; start = i; startline = line
        i += 1
        while i < n:
            if src[i] == '\\':
                i += 2; continue
            if src[i] == q:
                break
            if src[i] == '\n':
                line += 1
            i += 1
        if i >= n:
            err("unterminated string", start, startline)
            break
        i += 1
        prev_significant = 'str'
        continue
    if c in '([{':
        stack.append((c, line)); i += 1; continue
    if c in ')]}':
        if not stack:
            err("closing '%s' with empty stack" % c, i, line)
        else:
            o, ol = stack.pop()
            if o != pairs[c]:
                err("mismatched '%s' closing '%s' opened at line %d" % (c, o, ol), i, line)
        i += 1; continue
    i += 1

if stack:
    for o, ol in stack:
        err("unclosed '%s' opened at line %d" % (o, ol), n, ol)

print("lines:", src.count('\n') + 1, "errors:", len(errs))
for e in errs[:20]:
    print(" ", e)

