src = pathlib.Path('app_only.js').read_text()
i = 0
n = len(src)
line = 1
issues = []
while i < n:
    c = src[i]
    if c == '\n':
        line += 1; i += 1; continue
    if c == '/' and i + 1 < n and src[i + 1] == '/':
        while i < n and src[i] != '\n':
            i += 1
        continue
    if c == '/' and i + 1 < n and src[i + 1] == '*':
        sl = line
        i += 2
        while i + 1 < n and not (src[i] == '*' and src[i + 1] == '/'):
            if src[i] == '\n': line += 1
            i += 1
        i += 2
        continue
    if c == '"' or c == "'":
        q = c; sl = line
        i += 1
        while i < n:
            if src[i] == '\\':
                i += 2; continue
            if src[i] == q: break
            if src[i] == '\n': line += 1
            i += 1
        if i >= n:
            issues.append(("UNTERMINATED", sl, src.split('\n')[sl - 1][:120]))
            break
        i += 1
        continue
    i += 1
print("string issues:", len(issues))
for it in issues[:10]:
    print(" ", it)

# count quotes per line, ignoring // line comments and /* */ blocks
depth = 0
for idx, l in enumerate(src.split('\n'), 1):
    j = 0
    instr = None
    cnt = 0
    while j < len(l):
        c = l[j]
        if depth == 0 and c == '/' and j + 1 < len(l) and l[j+1] == '/':
            break
        if c == '/' and j + 1 < len(l) and l[j+1] == '*':
            depth += 1; j += 2; continue
        if depth > 0 and c == '*' and j + 1 < len(l) and l[j+1] == '/':
            depth -= 1; j += 2; continue
        if instr:
            if c == '\\': j += 2; continue
            if c == instr: instr = None
        else:
            if c == '"' or c == "'":
                instr = c
            elif c in '([{':
                cnt += 1
            elif c in ')]}':
                cnt -= 1
        j += 1
    if cnt != 0 and instr is None:
        print("  unbalanced brackets on line", idx, "delta", cnt, l[:110])

