    j = 0
    startline = True
    opened_here = None
    while j < len(l):
        c = l[j]
        if depth == 0 and c == '/' and j + 1 < len(l) and l[j+1] == '/':
            break
        if c == '/' and j + 1 < len(l) and l[j+1] == '*':
            depth += 1; j += 2; continue
        if depth > 0 and c == '*' and j + 1 < len(l) and l[j+1] == '/':
            depth -= 1; j += 2; continue
        if instr:
            if c == '\\':
                j += 2; continue
            if c == instr:
                instr = None
            elif c == '\n':
                print("STRING SPANS LINES at", idx, ":", l[:120])
        else:
            if c == '"' or c == "'":
                instr = c
                if opened_here is None:
                    opened_here = (j, c)
        j += 1
    if opened_here is not None and instr is not None:
        print("OPEN STRING at line", idx, "col", opened_here[0], "quote", opened_here[1], ":", l[:140])
        instr = None

