setFromAxisAngle: function (axis, angle) {
  var h = angle / 2, s = Math.sin(h);
  this.x = axis.x * s; this.y = axis.y * s; this.z = axis.z * s; this.w = Math.cos(h);
  return this;
},
setFromUnitVectors: function (a, b) {
  var r = a.dot(b) + 1;
  if (r < 1e-8) {
    r = 0;
    if (Math.abs(a.x) > Math.abs(a.z)) { this.x = -a.y; this.y = a.x; this.z = 0; this.w = r; }
    else { this.x = 0; this.y = -a.z; this.z = a.y; this.w = r; }
  } else {
    this.x = a.y * b.z - a.z * b.y;
    this.y = a.z * b.x - a.x * b.z;
    this.z = a.x * b.y - a.y * b.x;
    this.w = r;
  }
  return this.normalize();
},
normalize: function () {
  var l = Math.sqrt(this.x * this.x + this.y * this.y + this.z * this.z + this.w * this.w);
  if (l > 0) { this.x /= l; this.y /= l; this.z /= l; this.w /= l; }
  return this;
},

