/* Debug: why do the cars fall outside the frame? */
var A = window.__app;
function camAt(t) { A.renderAt(t); return { p: A.camera.position.clone(), fov: A.camera.fov, q: A.camera.quaternion.clone(), up: A.camera.up.clone() }; }
function camSpace(cam, p) {
  var v = p.clone().sub(cam.p);
  var q = new QT(); q.x = -cam.q.x; q.y = -cam.q.y; q.z = -cam.q.z; q.w = cam.q.w;
  v.applyQuaternion(q);
  return v;
}
var times = [11.5, 13.0, 16.0, 17.5, 19.75, 21.0, 25.0, 28.0, 31.0, 33.0, 35.0, 37.0, 39.0];
for (var i = 0; i < times.length; i++) {
  var t = times[i];
  var cam = camAt(t);
  var vr = camSpace(cam, A.cars.red.position);
  var vb = camSpace(cam, A.cars.blue.position);
  var vTan = Math.tan(cam.fov * Math.PI / 360);
  var hTan = vTan * (16 / 9);
  var mr = Math.max(Math.abs(vr.x) / -vr.z / hTan, Math.abs(vr.y) / -vr.z / vTan);
  var mb = Math.max(Math.abs(vb.x) / -vb.z / hTan, Math.abs(vb.y) / -vb.z / vTan);
  console.log('t=' + t +
    ' shot=' + A.shotIndex(t) +
    ' cam=' + cam.p.toArray().map(function (v) { return v.toFixed(1); }).join(',') +
    ' redCam=' + vr.toArray().map(function (v) { return v.toFixed(1); }).join(',') +
    ' blueCam=' + vb.toArray().map(function (v) { return v.toFixed(1); }).join(',') +
    ' mRed=' + mr.toFixed(2) + ' mBlue=' + mb.toFixed(2) +
    ' dRed=' + A.cars.red.position.distanceTo(A.cars.blue.position).toFixed(1));
}

