const SHOTS = [
  { t0: 0, t1: 5, fov: 35 },
  { t0: 5, t1: 11, fov: 50 },
  { t0: 11, t1: 15, fov: 24 },
  { t0: 15, t1: 20, fov: 75 },
  { t0: 20, t1: 24, fov: 28 },
  { t0: 24, t1: 30, fov: 30 },
  { t0: 30, t1: 34, fov: 30 },
  { t0: 34, t1: 40.001, fov: 32 }
];
const REF_ASPECT = 16 / 9;
function shotIndex(t) {
  for (let i = 0; i < SHOTS.length; i++) if (t >= SHOTS[i].t0 && t < SHOTS[i].t1) return i;
  return SHOTS.length - 1;
}
/* The listed FOVs are the reference (16:9) vertical fields.  On a narrower
   viewport the vertical field is widened so that the *horizontal* framing of
   the scheduled shot — and therefore both cars — is preserved exactly. */
function fovForShot(fovTable, aspect) {
  if (!aspect || aspect >= REF_ASPECT) return fovTable;
  const refHTan = Math.tan(fovTable * Math.PI / 360) * REF_ASPECT;
  return 2 * Math.atan(refHTan / aspect) * 180 / Math.PI;
}
const camPos = new THREE.Vector3(), camTgt = new THREE.Vector3(), camUp = new THREE.Vector3(0, 1, 0);
function applyCamera(t, kinR, kinB) {
  const mid = kinR.pos.clone().add(kinB.pos).multiplyScalar(0.5);
  const i = shotIndex(t);
  const sh = SHOTS[i];
  let fov = fovForShot(sh.fov, camera.aspect);
  camUp.set(0, 1, 0);

