input.new_string:
/* ---------- 8. both cars stay in frame ---------- */
function inFrame(cam, p, aspect) {
  var v = p.clone().sub(cam.p);
  var q = new QT();
  q.x = -cam.q.x; q.y = -cam.q.y; q.z = -cam.q.z; q.w = cam.q.w;
  v.applyQuaternion(q);
  var depth = -v.z;
  if (depth <= 0.05) return -1;
  var vTan = Math.tan(cam.fov * Math.PI / 360);
  var hTan = vTan * aspect;
  var mx = Math.abs(v.x) / depth / hTan;
  var my = Math.abs(v.y) / depth / vTan;
  return Math.max(mx, my);   /* <= 1 means inside the frame */
}
function framingSweep(aspect) {
  A.camera.aspect = aspect;
  var worst = 0, worstT = 0;
  for (var ts = 0; ts <= 40; ts += 0.1) {
    var cam = camAt(ts);
    /* in the onboard shot the host car is the camera platform: only the
       pursuing car has to stay inside the frame */
    var m = inFrame(cam, A.cars.red.position, aspect);
    if (A.shotIndex(ts) !== 3) {
      var mb = inFrame(cam, A.cars.blue.position, aspect);
      if (mb > m) m = mb;
    }
    if (m > worst) { worst = m; worstT = ts; }
  }
  A.camera.aspect = 16 / 9;
  return { worst: worst, t: worstT };
}
var f169 = framingSweep(16 / 9);
var fport = framingSweep(1280 / 1340);
check('both cars stay in frame at 16:9', f169.worst <= 1.0, 'worst=' + f169.worst.toFixed(3) + ' at t=' + f169.t);
check('both cars stay in frame at 1280x1340 portrait', fport.worst <= 1.0, 'worst=' + fport.worst.toFixed(3) + ' at t=' + fport.t);

