input.new_string:
for (const side of [-1, 1]) {
  /* vertical wall panel following the track, with true outward normals */
  const steps = 900;
  const p = [], nrm = [], uvs = [], idx = [];
  const c = new THREE.Vector3(), nv = new THREE.Vector3();
  for (let i = 0; i <= steps; i++) {
    const s = i / steps * L;
    C(s, c); N(s, nv);
    const bx = c.x + nv.x * side * 9.0, bz = c.z + nv.z * side * 9.0;
    const nx = nv.x * side, nz = nv.z * side;
    p.push(bx, c.y - 0.05, bz, bx, c.y + 0.95, bz);
    nrm.push(nx, 0, nz, nx, 0, nz);
    const v = s / L * 90;
    uvs.push(v, 0, v, 1);
    if (i < steps) {
      const a = i * 2;
      idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
      idx.push(a + 2, a + 1, a, a + 2, a + 3, a + 1);
    }
  }
  const gg = new THREE.BufferGeometry();
  gg.setAttribute('position', new THREE.Float32BufferAttribute(p, 3));
  gg.setAttribute('normal', new THREE.Float32BufferAttribute(nrm, 3));
  gg.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  gg.setIndex(idx);
  const m = new THREE.Mesh(gg, matBarrier);
  m.receiveShadow = true;
  scene.add(m);

  /* catch fence above the barrier */
  const fp = [], fn = [], fu = [], fi = [];
  for (let i = 0; i <= steps; i++) {
    const s = i / steps * L;
    C(s, c); N(s, nv);
    const bx = c.x + nv.x * side * 9.0, bz = c.z + nv.z * side * 9.0;
    const nx = nv.x * side, nz = nv.z * side;
    fp.push(bx, c.y + 0.95, bz, bx, c.y + 4.25, bz);
    fn.push(nx, 0, nz, nx, 0, nz);
    const v = s / L * 260;
    fu.push(v, 0, v, 1);
    if (i < steps) {
      const a = i * 2;
      fi.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
      fi.push(a + 2, a + 1, a, a + 2, a + 3, a + 1);
    }
  }
  const fgg = new THREE.BufferGeometry();
  fgg.setAttribute('position', new THREE.Float32BufferAttribute(fp, 3));
  fgg.setAttribute('normal', new THREE.Float32BufferAttribute(fn, 3));
  fgg.setAttribute('uv', new THREE.Float32BufferAttribute(fu, 2));
  fgg.setIndex(fi);
  scene.add(new THREE.Mesh(fgg, matFence));
}

