  var pos = this.attributes.position;
  if (!pos || !this.index) return this;
  var ix = Array.isArray(this.index) ? this.index : this.index.array;
  var nrm = new Float32Array(pos.array.length);
  for (var i = 0; i < ix.length; i += 3) {
    var a = ix[i], b = ix[i + 1], c = ix[i + 2];
    var ax = pos.getX(a), ay = pos.getY(a), az = pos.getZ(a);
    var bx = pos.getX(b), by = pos.getY(b), bz = pos.getZ(b);
    var cx = pos.getX(c), cy = pos.getY(c), cz = pos.getZ(c);
    var e1x = bx - ax, e1y = by - ay, e1z = bz - az;
    var e2x = cx - ax, e2y = cy - ay, e2z = cz - az;
    var nx = e1y * e2z - e1z * e2y, ny = e1z * e2x - e1x * e2z, nz = e1x * e2y - e1y * e2x;
    nrm[a * 3] += nx; nrm[a * 3 + 1] += ny; nrm[a * 3 + 2] += nz;
    nrm[b * 3] += nx; nrm[b * 3 + 1] += ny; nrm[b * 3 + 2] += nz;
    nrm[c * 3] += nx; nrm[c * 3 + 1] += ny; nrm[c * 3 + 2] += nz;
  }
  for (var k = 0; k < nrm.length; k += 3) {
    var l = Math.sqrt(nrm[k] * nrm[k] + nrm[k + 1] * nrm[k + 1] + nrm[k + 2] * nrm[k + 2]);
