/* Geometry validation: winding, orientation and dimensions of generated meshes */
var A = window.__app;
var FAILS2 = [];
function check2(name, cond, detail) {
  if (cond) console.log('PASS  ' + name + (detail ? '  [' + detail + ']' : ''));
  else { console.log('FAIL  ' + name + (detail ? '  [' + detail + ']' : '')); FAILS2.push(name); }
}
function signedVolume(geo) {
  var pos = geo.getAttribute('position'), idx = geo.index;
  if (!pos || !idx) return null;
  var ix = Array.isArray(idx) ? idx : idx.array;
  var v = 0;
  for (var i = 0; i < ix.length; i += 3) {
    var a = ix[i], b = ix[i + 1], c = ix[i + 2];
    var ax = pos.getX(a), ay = pos.getY(a), az = pos.getZ(a);
    var bx = pos.getX(b), by = pos.getY(b), bz = pos.getZ(b);
    var cx = pos.getX(c), cy = pos.getY(c), cz = pos.getZ(c);
    v += (ax * (by * cz - bz * cy) + ay * (bz * cx - bx * cz) + az * (bx * cy - by * cx)) / 6;
  }
  return v;
}
function avgNormalY(geo) {
  var n = geo.getAttribute('normal');
  if (!n) return null;
  var sy = 0, s = 0;
  for (var i = 0; i < n.count; i++) { sy += n.getY(i); s++; }
  return sy / s;
}
function bbox(meshes) {
  var mn = [1e9, 1e9, 1e9], mx = [-1e9, -1e9, -1e9], any = false;
  meshes.forEach(function (m) {
    var g = m.geometry;
    if (!g || !g.getAttribute) return;
    var pos = g.getAttribute('position');
    if (!pos) return;
    any = true;
    for (var i = 0; i < pos.count; i++) {
      var x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
      if (x < mn[0]) mn[0] = x; if (x > mx[0]) mx[0] = x;
      if (y < mn[1]) mn[1] = y; if (y > mx[1]) mx[1] = y;
      if (z < mn[2]) mn[2] = z; if (z > mx[2]) mx[2] = z;
    }
  });
  return any ? { mn: mn, mx: mx } : null;
}

/* --- car bodywork: every lofted shell must wind outward --- */
var carMeshes = [];
A.cars.red.traverse(function (o) { if (o.geometry && o.geometry.getAttribute) carMeshes.push(o); });
var vols = [], neg = [];
carMeshes.forEach(function (m, i) {
  var v = signedVolume(m.geometry);
  if (v === null) return;
  vols.push(v);
  if (v < 0) neg.push(i);
});
check2('lofted bodywork winds outward (positive volume)', neg.length === 0,
  neg.length === 0 ? (vols.length + ' closed shells, min V=' + Math.min.apply(null, vols).toFixed(4))
    : (neg.length + ' inverted shells'));

/* --- car dimensions --- */
var bb = bbox(carMeshes);
if (bb) {
  var Lx = bb.mx[0] - bb.mn[0], Ly = bb.mx[1] - bb.mn[1], Lz = bb.mx[2] - bb.mn[2];
  check2('car length ~5.5 m', Lx > 4.8 && Lx < 6.2, 'lofted length=' + Lx.toFixed(2) + ' m');
  check2('car height ~0.95 m', Ly > 0.75 && Ly < 1.15, 'lofted height=' + Ly.toFixed(2) + ' m');
  check2('car width ~2.0 m', Lz > 1.4 && Lz < 2.4, 'lofted width=' + Lz.toFixed(2) + ' m');
  check2('car floor sits at y=0', bb.mn[1] > -0.06 && bb.mn[1] < 0.06, 'min y=' + bb.mn[1].toFixed(3));
  check2('car nose points +X', bb.mx[0] > 2.4 && bb.mn[0] < -2.2, 'x range ' + bb.mn[0].toFixed(2) + '..' + bb.mx[0].toFixed(2));
}

/* --- road and kerbs face up --- */
var roadY = null, kerbYs = [];
A.scene.children.forEach(function (o) {
  if (!o.geometry || !o.geometry.getAttribute) return;
  var ny = avgNormalY(o.geometry);
  if (ny === null) return;
  var pos = o.geometry.getAttribute('position');
  var count = pos.count;
  var span = 0;
  for (var i = 0; i < count; i += Math.max(1, Math.floor(count / 50))) {
    span = Math.max(span, Math.abs(pos.getY(i)));
  }
  if (count > 2000 && span < 40 && roadY === null && ny > 0) roadY = ny;
  else if (count > 10 && count < 2000 && span < 40) kerbYs.push(ny);
});
check2('road surface normals point up', roadY !== null && roadY > 0.9, 'avg ny=' + (roadY === null ? 'n/a' : roadY.toFixed(3)));
var badKerbs = kerbYs.filter(function (v) { return v < 0.5; });
check2('kerb/edge ribbons face up', badKerbs.length === 0, kerbYs.length + ' ribbons checked, ' + badKerbs.length + ' facing down');

/* --- the road ribbon spans the full 14 m width --- */
var widthOk = false, wDetail = '';
A.scene.children.forEach(function (o) {
  if (!o.geometry || !o.geometry.getAttribute) return;
  var pos = o.geometry.getAttribute('position');
  if (!pos || pos.count < 2000) return;
  var minx = 1e9, maxx = -1e9, minz = 1e9, maxz = -1e9, miny = 1e9, maxy = -1e9;
  for (var i = 0; i < pos.count; i++) {
    var x = pos.getX(i), z = pos.getZ(i), y = pos.getY(i);
    if (x < minx) minx = x; if (x > maxx) maxx = x;
    if (z < minz) minz = z; if (z > maxz) maxz = z;
    if (y < miny) miny = y; if (y > maxy) maxy = y;
  }
  if (maxx - minx > 300 && maxz - minz > 300) {
    widthOk = true;
    wDetail = 'bbox x ' + minx.toFixed(0) + '..' + maxx.toFixed(0) + ' z ' + minz.toFixed(0) + '..' + maxz.toFixed(0) +
      ' y ' + miny.toFixed(1) + '..' + maxy.toFixed(1);
  }
});
check2('road ribbon spans the whole circuit footprint', widthOk, wDetail);

/* --- particle buffers are finite --- */
var finite = true;
A.scene.children.forEach(function (o) {
  if (!o.geometry || !o.geometry.getAttribute) return;
  var pos = o.geometry.getAttribute('position');
  if (!pos) return;
  for (var i = 0; i < pos.count * 3; i++) if (!isFinite(pos.array[i])) { finite = false; break; }
});
check2('all particle positions are finite', finite);

console.log(FAILS2.length ? 'GEOMETRY FAILURES: ' + FAILS2.join(' | ') : 'GEOMETRY OK');

