var carMeshes = [];
A.cars.red.traverse(function (o) { if (o.geometry && o.geometry.getAttribute) carMeshes.push(o); });
var vols = [], neg = [], details = [];
carMeshes.forEach(function (m, i) {
  var v = signedVolume(m.geometry);
  if (v === null) return;
  vols.push(v);
  var g = m.geometry, pos = g.getAttribute('position'), nrm = g.getAttribute('normal');
  var cxx = 0, cyy = 0, czz = 0;
  for (var k = 0; k < pos.count; k++) { cxx += pos.getX(k); cyy += pos.getY(k); czz += pos.getZ(k); }
  cxx /= pos.count; cyy /= pos.count; czz /= pos.count;
  var out = 0;
  if (nrm) {
    for (var k2 = 0; k2 < pos.count; k2++) {
      var dx = pos.getX(k2) - cxx, dy = pos.getY(k2) - cyy, dz = pos.getZ(k2) - czz;
      var dl = Math.sqrt(dx * dx + dy * dy + dz * dz) || 1;
      var dp = (dx * nrm.getX(k2) + dy * nrm.getY(k2) + dz * nrm.getZ(k2)) / dl;
      if (dp > 0) out++;
    }
  }
  var frac = out / pos.count;
  /* a closed shell must have positive volume; open shells are judged by normals */
  if (frac < 0.85 || (v < 0 && Math.abs(v) > 0.05)) {
    neg.push(i);
    details.push('v=' + v.toFixed(3) + ' verts=' + pos.count + ' outwardFrac=' + frac.toFixed(2));
  }
});
check2('bodywork shells face outward', neg.length === 0,
  neg.length === 0 ? (vols.length + ' shells checked') : (neg.length + ' bad: ' + details.slice(0, 4).join(' ; ')));

/* which part is tallest? */
var topName = '', topY = -1e9;
carMeshes.forEach(function (m) {
  var pos = m.geometry.getAttribute('position');
  if (!pos) return;
  for (var i = 0; i < pos.count; i++) if (pos.getY(i) > topY) { topY = pos.getY(i); }
});
console.log('INFO  tallest lofted point y=' + topY.toFixed(3));

