#!/usr/bin/env python3
"""Build a debuggable copy of index.html outside the deliverable folder."""
import re, pathlib

SRC = pathlib.Path("/private/tmp/pcd-sbx-minimax-m3.1-flash-2qbro9mc/work/index.html")
DST = pathlib.Path("/private/tmp/pcd-sbx-minimax-m3.1-flash-2qbro9mc/dev/debug.html")

html = SRC.read_text()

# 1. error trapping installed BEFORE anything else runs
head_inject = """
<script>
window.__errs = [];
window.addEventListener('error', function (e) {
  var msg = 'PAGE-ERROR: ' + (e.message || '') + ' @' + (e.lineno || 0) + ':' + (e.colno || 0)
    + (e.filename ? ' (' + e.filename + ')' : '');
  window.__errs.push(msg);
  try { dump(msg + '\\n'); } catch (x) {}
}, true);
window.addEventListener('unhandledrejection', function (e) {
  try { dump('REJECT: ' + e.reason + '\\n'); } catch (x) {}
});
var __oe = console.error;
console.error = function () {
  try { dump('CONSOLE-ERROR: ' + Array.prototype.join.call(arguments, ' ') + '\\n'); } catch (x) {}
  __oe.apply(console, arguments);
};
var __ow = console.warn;
console.warn = function () {
  try { dump('CONSOLE-WARN: ' + Array.prototype.join.call(arguments, ' ') + '\\n'); } catch (x) {}
  __ow.apply(console, arguments);
};
try { dump('HEAD-OK three=' + (typeof THREE) + '\\n'); } catch (x) {}
</script>
"""
html = html.replace("</head>", head_inject + "</head>")

# 2. expose internals for deterministic single-frame capture
hook = """
window.__dbg = function (t) {
  state = 'PAUSED';
  simTime = t;
  setPlayingIcons(false);
  elScrub.value = t.toFixed(3);
  renderAt(t);
  try { dump('DBG renderAt ' + t + ' ok\\n'); } catch (x) {}
};
window.__diag = function () {
  var kinR = carRed.userData.kin, kinB = carBlue.userData.kin;
  dump('DIAG L=' + L.toFixed(2) + ' redS=' + kinR.s.toFixed(2) + ' blueS=' + kinB.s.toFixed(2)
    + ' sceneChildren=' + scene.children.length
    + ' redMeshes=' + carRed.children.length + ' blueMeshes=' + carBlue.children.length
    + ' drawCalls=' + renderer.info.render.calls + ' tris=' + renderer.info.render.triangles + '\\n');
};
"""
anchor = "/* ------------------------------------------------------------------ *\n * 26. Boot"
assert anchor in html
html = html.replace(anchor, hook + anchor)

# 3. run a diagnostic + requested frame once the script has booted
boot_extra = """
(function () {
  try {
    var m = /[?&]t=([0-9.]+)/.exec(location.search);
    if (m) window.__dbg(parseFloat(m[1]));
    if (window.__diag) window.__diag();
    try { dump('BOOT-COMPLETE errs=' + window.__errs.length + '\\n'); } catch (x) {}
  } catch (e) { try { dump('BOOT-ERROR: ' + e.message + ' | ' + e.stack + '\\n'); } catch (x) {} }
})();
"""
html = html.replace("</script>\n</body>", boot_extra + "</script>\n</body>")

DST.write_text(html)
print("wrote", DST, len(html), "bytes")

