    i = (y * w + x) * bpp
    if ctype == 3:
        idx = out[i]
        return plte[idx * 3], plte[idx * 3 + 1], plte[idx * 3 + 2]
    if ctype == 6:
        return out[i], out[i + 1], out[i + 2]
    if ctype == 2:
