#!/usr/bin/env python3
"""Minimal PNG reader + luminance probe (no external deps)."""
import zlib, struct, sys


def read_png(path):
    data = open(path, 'rb').read()
    assert data[:8] == b'\x89PNG\r\n\x1a\n', 'not a png'
    pos = 8
    idat = b''
    w = h = bitd = ctype = None
    plte = None
    while pos < len(data):
        ln = struct.unpack('>I', data[pos:pos + 4])[0]
        typ = data[pos + 4:pos + 8]
        chunk = data[pos + 8:pos + 8 + ln]
        if typ == b'IHDR':
            w, h, bitd, ctype = struct.unpack('>IIBB', chunk[:10])
        elif typ == b'PLTE':
            plte = chunk
        elif typ == b'IDAT':
            idat += chunk
        elif typ == b'IEND':
            break
        pos += 12 + ln
    raw = zlib.decompress(idat)
    if ctype == 6:
        bpp = 4
    elif ctype == 2:
        bpp = 3
    elif ctype == 0:
        bpp = 1
    elif ctype == 3:
        bpp = 1
    else:
        raise SystemExit('unsupported colour type ' + str(ctype))
    stride = w * bpp
    out = bytearray(h * stride)
    prev = bytearray(stride)
    p = 0
    for y in range(h):
        f = raw[p]; p += 1
        line = bytearray(raw[p:p + stride]); p += stride
        if f == 1:
            for i in range(bpp, stride):
                line[i] = (line[i] + line[i - bpp]) & 255
        elif f == 2:
            for i in range(stride):
                line[i] = (line[i] + prev[i]) & 255
        elif f == 3:
            for i in range(stride):
                a = line[i - bpp] if i >= bpp else 0
                line[i] = (line[i] + ((a + prev[i]) >> 1)) & 255
        elif f == 4:
            for i in range(stride):
                a = line[i - bpp] if i >= bpp else 0
                b = prev[i]
                c = prev[i - bpp] if i >= bpp else 0
                pp = a + b - c
                pa, pb, pc = abs(pp - a), abs(pp - b), abs(pp - c)
                pr = a if (pa <= pb and pa <= pc) else (b if pb <= pc else c)
                line[i] = (line[i] + pr) & 255
        out[y * stride:(y + 1) * stride] = line
        prev = line
    return w, h, bpp, ctype, plte, out


def pixel(out, w, bpp, ctype, plte, x, y):
    i = (y * w + x) * bpp
    if ctype == 3:
        idx = out[i]
        return plte[idx * 3], plte[idx * 3 + 1], plte[idx * 3 + 2]
    if ctype == 6:
        return out[i], out[i + 1], out[i + 2]
    if ctype == 2:
        return out[i], out[i + 1], out[i + 2]
    v = out[i]
    return v, v, v


def srgb_lum(r, g, b):
    return (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255.0


def main(path, regions):
    w, h, bpp, ctype, plte, out = read_png(path)
    print("image %s  %dx%d" % (path, w, h))
    for name, x0, y0, x1, y1 in regions:
        vals = []
