{
  const s = 2;
  const p = C(s, new THREE.Vector3());
  const n = N(s, new THREE.Vector3());
  const t = T(s, new THREE.Vector3());
  gantry.position.copy(p);
  gantry.quaternion.setFromRotationMatrix(
    new THREE.Matrix4().makeBasis(n.clone(), UP, t.clone())
  );
  const matGantry = new THREE.MeshStandardMaterial({ color: SC(0x23272e), roughness: 0.6, metalness: 0.55 });
  const postGeo = new THREE.BoxGeometry(0.55, 7.4, 0.55);
  for (const side of [-1, 1]) {
    const post = new THREE.Mesh(postGeo, matGantry);
    post.position.set(0, 3.7, side * 10.4);
    post.castShadow = true;
    gantry.add(post);
    const foot = new THREE.Mesh(new THREE.BoxGeometry(1.3, 0.4, 1.3), matGantry);
    foot.position.set(0, 0.2, side * 10.4);
    gantry.add(foot);
  }
  const beam = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.85, 21.4), matGantry);
  beam.position.set(0, 7.1, 0);

