#!/usr/bin/env python3
"""Build a debuggable copy of index.html outside the deliverable folder."""
import re, pathlib

SRC = pathlib.Path("/private/tmp/pcd-sbx-minimax-m3.1-flash-2qbro9mc/work/index.html")
DST = pathlib.Path("/private/tmp/pcd-sbx-minimax-m3.1-flash-2qbro9mc/dev/debug.html")

html = SRC.read_text()

# 1. error trapping installed BEFORE anything else runs
head_inject = """
<script>
window.__errs = [];
window.addEventListener('error', function (e) {
  var msg = 'PAGE-ERROR: ' + (e.message || '') + ' @' + (e.lineno || 0) + ':' + (e.colno || 0)
    + (e.filename ? ' (' + e.filename + ')' : '');
  try { dump('STACK: ' + (e.error && e.error.stack ? e.error.stack : 'no stack') + '\\n'); } catch (x) {}
  window.__errs.push(msg);
  try { dump(msg + '\\n'); } catch (x) {}
}, true);
window.addEventListener('unhandledrejection', function (e) {
  try { dump('REJECT: ' + e.reason + '\\n'); } catch (x) {}
});
var __oe = console.error;
console.error = function () {
  try { dump('CONSOLE-ERROR: ' + Array.prototype.join.call(arguments, ' ') + '\\n'); } catch (x) {}
  __oe.apply(console, arguments);
};
var __ow = console.warn;
console.warn = function () {
  try { dump('CONSOLE-WARN: ' + Array.prototype.join.call(arguments, ' ') + '\\n'); } catch (x) {}
  __ow.apply(console, arguments);
};
try { dump('HEAD-OK three=' + (typeof THREE) + '\\n'); } catch (x) {}
</script>
"""
html = html.replace("</head>", head_inject + "</head>")

# 2. expose internals for deterministic single-frame capture
hook = """
window.__dbg = function (t) {
  state = 'PAUSED';
  simTime = t;
  setPlayingIcons(false);
  elScrub.value = t.toFixed(3);
  renderAt(t);
  try { dump('DBG renderAt ' + t + ' ok\\n'); } catch (x) {}
};
window.__shot = function (name) {
  try {
    var url = renderer.domElement.toDataURL('image/png');
    var xhr = new XMLHttpRequest();
    xhr.open('POST', '/save?name=' + encodeURIComponent(name), false);
    xhr.send(url);
    dump('SHOT-SAVED ' + name + ' bytes=' + url.length + '\\n');
  } catch (e) { try { dump('SHOT-FAIL ' + e.message + '\\n'); } catch (x) {} }
};
window.__diag = function () {
  var kinR = carRed.userData.kin, kinB = carBlue.userData.kin;
  dump('DIAG L=' + L.toFixed(2) + ' redS=' + kinR.s.toFixed(2) + ' blueS=' + kinB.s.toFixed(2)
    + ' sceneChildren=' + scene.children.length
    + ' redMeshes=' + carRed.children.length + ' blueMeshes=' + carBlue.children.length
    + ' drawCalls=' + renderer.info.render.calls + ' tris=' + renderer.info.render.triangles + '\\n');
};
"""
anchor = "/* ------------------------------------------------------------------ *\n * 26. Boot"
assert anchor in html
html = html.replace(anchor, hook + anchor)

# 3. run a diagnostic + requested frame once the script has booted
boot_extra = """
(function () {
  try {
    var m = /[?&]t=([0-9.]+)/.exec(location.search);
    var list = /[?&]times=([0-9.,]+)/.exec(location.search);
    var nm = /[?&]n=([A-Za-z0-9_.-]+)/.exec(location.search);
    var tag = nm ? nm[1] : 'frame';
    if (list) {
      var arr = list[1].split(',');
      for (var i = 0; i < arr.length; i++) {
        var tt = parseFloat(arr[i]);
        window.__dbg(tt);
        window.__shot(tag + '_t' + String(arr[i]).replace('.', 'p') + '.png');
      }
    } else if (m) {
      window.__dbg(parseFloat(m[1]));
      window.__shot(tag + '.png');
    }
    if (window.__diag) window.__diag();
    try { dump('BOOT-COMPLETE errs=' + window.__errs.length + '\\n'); } catch (x) {}
  } catch (e) { try { dump('BOOT-ERROR: ' + e.message + ' | ' + e.stack + '\\n'); } catch (x) {} }
})();
"""
html = html.replace("</script>\n</body>", boot_extra + "</script>\n</body>")

# DEBUG ONLY: use the local copy of the same three.js r128 build so that
# error stacks are not sanitised cross-origin
html = html.replace('<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>',
                    '<script src="three_local.js"></script>\n'
                    + '<script>\n'
                    + 'try {\n'
                    + '  var __io = THREE.Frustum.prototype.intersectsObject;\n'
                    + '  THREE.Frustum.prototype.intersectsObject = function (obj) {\n'
                    + '    try { return __io.call(this, obj); }\n'
                    + '    catch (e) {\n'
                    + '      try { dump("FAILOBJ type=" + obj.type + " geoType=" + (obj.geometry && obj.geometry.type)\n'
                    + '        + " geoBS=" + (obj.geometry ? (obj.geometry.boundingSphere === null ? "null" : typeof obj.geometry.boundingSphere) : "nogeo")\n'
                    + '        + " objBS=" + (obj.boundingSphere === null ? "null" : typeof obj.boundingSphere)\n'
                    + '        + " posCount=" + (obj.geometry && obj.geometry.attributes && obj.geometry.attributes.position ? obj.geometry.attributes.position.count : -1)\n'
                    + '        + " hasIndex=" + (obj.geometry ? !!obj.geometry.index : false)\n'
                    + '        + "\\n"); } catch (x) {}\n'
                    + '      throw e;\n'
                    + '    }\n'
                    + '  };\n'
                    + '} catch (e) { try { dump("PATCH-FAIL " + e.message + "\\n"); } catch (x) {} }\n'
                    + '</script>')

# DEBUG ONLY: preserve the drawing buffer so headless screenshots capture WebGL
html = html.replace("antialias: true, alpha: true, powerPreference: 'high-performance'",
                    "antialias: true, alpha: true, preserveDrawingBuffer: true, powerPreference: 'high-performance'")
DST.write_text(html)
print("wrote", DST, len(html), "bytes")

