html = html.replace(anchor, hook + anchor)

# 3. run a diagnostic + requested frame once the script has booted
boot_extra = """
(function () {
  try {
    var m = /[?&]t=([0-9.]+)/.exec(location.search);
    var list = /[?&]times=([0-9.,]+)/.exec(location.search);
    var nm = /[?&]n=([A-Za-z0-9_.-]+)/.exec(location.search);
    var tag = nm ? nm[1] : 'frame';
    if (list) {
      var arr = list[1].split(',');
      for (var i = 0; i < arr.length; i++) {
        var tt = parseFloat(arr[i]);
        window.__dbg(tt);
        window.__shot(tag + '_t' + String(arr[i]).replace('.', 'p') + '.png');
      }
    } else if (m) {
      window.__dbg(parseFloat(m[1]));
      window.__shot(tag + '.png');
    }
    if (window.__diag) window.__diag();
    try { dump('BOOT-COMPLETE errs=' + window.__errs.length + '\\n'); } catch (x) {}
  } catch (e) { try { dump('BOOT-ERROR: ' + e.message + ' | ' + e.stack + '\\n'); } catch (x) {} }
})();
"""
html = html.replace("</script>\n</body>", boot_extra + "</script>\n</body>")

# DEBUG ONLY: use the local copy of the same three.js r128 build so that
# error stacks are not sanitised cross-origin
html = html.replace('<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>',
                    '<script src="three_local.js"></script>\n'
                    + '<script>\n'
                    + 'try {\n'
                    + '  var __io = THREE.Frustum.prototype.intersectsObject;\n'
                    + '  THREE.Frustum.prototype.intersectsObject = function (obj) {\n'
                    + '    try { return __io.call(this, obj); }\n'
                    + '    catch (e) {\n'
                    + '      try { dump("FAILOBJ type=" + obj.type + " geoType=" + (obj.geometry && obj.geometry.type)\n'
                    + '        + " geoBS=" + (obj.geometry ? (obj.geometry.boundingSphere === null ? "null" : typeof obj.geometry.boundingSphere) : "nogeo")\n'
                    + '        + " objBS=" + (obj.boundingSphere === null ? "null" : typeof obj.boundingSphere)\n'
                    + '        + " posCount=" + (obj.geometry && obj.geometry.attributes && obj.geometry.attributes.position ? obj.geometry.attributes.position.count : -1)\n'
                    + '        + " hasIndex=" + (obj.geometry ? !!obj.geometry.index : false)\n'
                    + '        + "\\n"); } catch (x) {}\n'
                    + '      throw e;\n'
                    + '    }\n'
                    + '  };\n'
                    + '} catch (e) { try { dump("PATCH-FAIL " + e.message + "\\n"); } catch (x) {} }\n'
                    + '</script>')

# DEBUG ONLY: preserve the drawing buffer so headless screenshots capture WebGL
html = html.replace("antialias: true, alpha: true, powerPreference: 'high-performance'",
                    "antialias: true, alpha: true, preserveDrawingBuffer: true, powerPreference: 'high-performance'")
DST.write_text(html)
print("wrote", DST, len(html), "bytes")

