const camPos = new THREE.Vector3(), camTgt = new THREE.Vector3(), camUp = new THREE.Vector3(0, 1, 0);
function applyCamera(t, kinR, kinB) {
  const mid = kinR.pos.clone().add(kinB.pos).multiplyScalar(0.5);
  const i = shotIndex(t);
  const sh = SHOTS[i];
  let fov = fovForShot(sh.fov, camera.aspect);
  camUp.set(0, 1, 0);
  if (i === 0) {
    camPos.set(-34, 2.6, 0); camTgt.set(0, 3.0, 0);
  } else if (i === 1) {
    const s = kinB.s;
    C(s - 9, camPos); N(s, _n);
    camPos.addScaledVector(_n, kinB.d).add(new THREE.Vector3(0, 2.4, 0));
    C(s + 14, camTgt); camTgt.y += 0.9;
  } else if (i === 2) {
    C(400, camPos); N(400, _n);
    camPos.addScaledVector(_n, -18).add(new THREE.Vector3(0, 5, 0));
    camTgt.copy(mid);
  } else if (i === 3) {
    /* rigid blue T-cam */
    const local = new THREE.Vector3(-0.55, 1.25, 0).applyQuaternion(carBlue.quaternion);
    camPos.copy(carBlue.position).add(local);
    camUp.set(0, 1, 0).applyQuaternion(carBlue.quaternion).normalize();
    const ahead = new THREE.Vector3(1, 0, 0).applyQuaternion(carBlue.quaternion).multiplyScalar(40);
    camTgt.copy(carBlue.position).add(ahead);
    const roadY = C(kinB.s + 40, new THREE.Vector3()).y;
    camTgt.y = roadY + 0.6;
  } else if (i === 4) {
    C(725, camPos); N(725, _n);
    camPos.addScaledVector(_n, 20).add(new THREE.Vector3(0, 3, 0));
    camTgt.copy(mid);
  } else if (i === 5) {
    camPos.set(-80, 120, 150);
    camTgt.copy(mid);
  } else if (i === 6) {
    C(1300, camPos); N(1300, _n);
    camPos.addScaledVector(_n, -12).add(new THREE.Vector3(0, 1.2, 0));
    camTgt.copy(mid);
  } else {
    camPos.set(-20, 4.5, 15);
    camTgt.copy(mid);
  }
  camera.position.copy(camPos);
  camera.up.copy(camUp);
  camera.lookAt(camTgt);
  if (camera.fov !== fov) { camera.fov = fov; camera.updateProjectionMatrix(); }
  return i;
}

/* ------------------------------------------------------------------ *
 * 21. Synthesized sound (Web Audio only, no files, no music)
 * ------------------------------------------------------------------ */
const AudioSys = (function () {
  const AC = window.AudioContext || window.webkitAudioContext;
  let ctx = null, master = null, comp = null, noiseBuf = null, ready = false;
  const cars = [];
  let crowd = null, hum = null, breeze = null, wind = null;
  const oneShots = [];

  function makeNoise(seconds) {
    const len = Math.floor(ctx.sampleRate * seconds);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = rngAudio() * 2 - 1;
    return buf;
  }
  function noiseSource() {
    const s = ctx.createBufferSource();
    s.buffer = noiseBuf; s.loop = true;
    s.start(0);
    return s;
  }
  function panner() {
    const p = ctx.createPanner();
    p.panningModel = 'HRTF';
    p.distanceModel = 'inverse';
    p.refDistance = 7; p.maxDistance = 400; p.rolloffFactor = 1.05;
    return p;
  }

