textFile.content:
  beam.position.set(0, 7.1, 0);
  beam.castShadow = true;
  gantry.add(beam);
  const fascia = new THREE.Mesh(new THREE.BoxGeometry(0.1, 1.5, 21.4),
    new THREE.MeshStandardMaterial({ color: SC(0x15181e), roughness: 0.5, metalness: 0.3 }));
  fascia.position.set(-0.36, 6.3, 0);
  gantry.add(fascia);
  /* five light pods facing the grid (-X of the gantry frame) */
  const housingMat = new THREE.MeshStandardMaterial({ color: SC(0x0d0f13), roughness: 0.5, metalness: 0.4 });
  gantry.userData.lights = [];
  for (let i = 0; i < 5; i++) {
    const pod = new THREE.Group();
    pod.position.set(-0.42, 5.55, (i - 2) * 1.55);
    const housing = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.95, 1.15), housingMat);
    pod.add(housing);
    const lensMat = new THREE.MeshBasicMaterial({ color: SC(0x2a0608) });
    const lens = new THREE.Mesh(new THREE.CircleGeometry(0.34, 20), lensMat);
    lens.position.set(-0.22, 0.05, 0);
    lens.rotation.y = -Math.PI / 2;
    pod.add(lens);
    /* rear repeater so the sequence is visible from behind too */
    const repMat = new THREE.MeshBasicMaterial({ color: SC(0x2a0608) });
    const rep = new THREE.Mesh(new THREE.CircleGeometry(0.17, 16), repMat);
    rep.position.set(0.23, 0.05, 0);
    rep.rotation.y = Math.PI / 2;
    pod.add(rep);
    const g = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTex, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true,
      color: SC(0xff3020), opacity: 0, fog: false
    }));
    g.scale.set(2.6, 2.6, 1);
    g.position.set(-0.3, 0.05, 0);
    pod.add(g);
    gantry.add(pod);
    gantry.userData.lights.push({ lens: lensMat, repeater: repMat, glow: g.material });
  }
  scene.add(gantry);
}

/* chequered start / finish line */
{
  const g = ribbon({ steps: 2, s0: -0.7, s1: 0.7, inner: -ROAD_HALF, outer: ROAD_HALF, y: () => 0.016 });
  const uvs = g.getAttribute('uv');
  const m = new THREE.Mesh(g, new THREE.MeshStandardMaterial({
    map: tex(chequerTexture(), 1, 1, true), roughness: 0.4, metalness: 0.05
  }));
  m.receiveShadow = true;
  scene.add(m);
}

/* two painted grid boxes */
function gridBox(s, d) {
  const grp = new THREE.Group();
  const p = C(s, new THREE.Vector3());
  const n = N(s, new THREE.Vector3());
  const t = T(s, new THREE.Vector3());
  grp.position.copy(p).addScaledVector(n, d);
  grp.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(t.clone(), UP, n.clone()));
  const mat = new THREE.MeshStandardMaterial({ color: SC(0xdfe3e8), roughness: 0.55, metalness: 0.04 });
  const Lb = 5.2, Wb = 2.45, w = 0.14;
  const mk = (x, z, sx, sz) => {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(sx, sz), mat);
    m.rotation.x = -Math.PI / 2;
    m.position.set(x, 0.02, z);
    m.receiveShadow = true;
    grp.add(m);
  };
  mk(0, -Wb / 2, Lb, w); mk(0, Wb / 2, Lb, w);
  mk(-Lb / 2, 0, w, Wb); mk(Lb / 2, 0, w, Wb);
  scene.add(grp);

