textFile.content:
/* baked pools of floodlight on the damp road */
const poolGeo = ribbon({
  steps: 1500, inner: -ROAD_HALF, outer: ROAD_HALF, y: () => 0.022,
  color: (s, u) => {
    const d = lerp(-ROAD_HALF, ROAD_HALF, u);
    let I = 0;
    for (const m of MASTS) {
      let ds = s - m.s;
      ds = mod(ds + L / 2, L) - L / 2;
      const dd = d - m.side * 1.6;
      const r = (ds * ds) / (13.5 * 13.5) + (dd * dd) / (6.8 * 6.8);
      if (r < 1) { const f = 1 - r; I += f * f * f * 0.95; }
    }
    I = Math.min(I, 1.0);
    return [I * 0.92, I * 0.90, I * 0.84];
  }
});
const matPool = new THREE.MeshBasicMaterial({
  vertexColors: true, transparent: true, opacity: 0.42, blending: THREE.AdditiveBlending,
  depthWrite: false, fog: true
});
scene.add(new THREE.Mesh(poolGeo, matPool));

/* ------------------------------------------------------------------ *
 * 11. Start gantry with five light pods, grid boxes, start line
 * ------------------------------------------------------------------ */
const gantry = new THREE.Group();
