/* =========================================================================
   Assertions run against the live application internals.
   ========================================================================= */
var FAILS = [];
function check(name, cond, detail) {
  if (cond) say('PASS  ' + name + (detail ? '  [' + detail + ']' : ''));
  else { say('FAIL  ' + name + (detail ? '  [' + detail + ']' : '')); FAILS.push(name); }
}
function near(a, b, tol) { return Math.abs(a - b) <= tol; }
function vfmt(v) { return '(' + v.x.toFixed(2) + ', ' + v.y.toFixed(2) + ', ' + v.z.toFixed(2) + ')'; }

/* ---------- 1. boot ---------- */
check('app booted and exported internals', typeof window.__app === 'object');
var A = window.__app;
if (!A) { say('ABORT'); } else {

/* ---------- 2. track ---------- */
check('lap length ~1552 m', near(A.L, 1552, 6), 'L=' + A.L.toFixed(2));
var c0 = A.C(0), n0 = A.N(0), t0v = A.T(0);
check('start line at origin', near(c0.x, 0, 0.01) && near(c0.y, 0, 0.01) && near(c0.z, 0, 0.01), vfmt(c0));
check('right-hand normal at s=0 is +Z', near(n0.x, 0, 0.001) && near(n0.y, 0, 0.001) && near(n0.z, 1, 0.001), vfmt(n0));
check('tangent at s=0 is +X', near(t0v.x, 1, 0.01) && near(t0v.z, 0, 0.02), vfmt(t0v));
var cEnd = A.C(A.L);
check('centreline closes on itself', cEnd.distanceTo(c0) < 0.6, 'gap=' + cEnd.distanceTo(c0).toFixed(3));

/* ---------- 3. checkpoint table / motion ---------- */
function sOf(t, sp) { return sp.eval(t).v; }
var tFinishB = null, tFinishR = null;
for (var t = 0; t <= 40; t += 0.001) {
  if (tFinishB === null && sOf(t, A.splineB) >= A.L) tFinishB = t;
  if (tFinishR === null && sOf(t, A.splineR) >= A.L) tFinishR = t;
}
check('blue crosses the line ~36.49 s', near(tFinishB, 36.49, 0.12), 't=' + tFinishB.toFixed(3));
check('red crosses the line ~36.54 s', near(tFinishR, 36.54, 0.12), 't=' + tFinishR.toFixed(3));
check('finish margin ~3.3 m', near(sOf(tFinishB, A.splineR), A.L, 4.5), 'gap=' + (A.L - sOf(tFinishB, A.splineR)).toFixed(2) + ' m');
var tLevel = null;
for (var t2 = 30; t2 <= 40; t2 += 0.001) {
  var gapPrev = sOf(t2 - 0.01, A.splineR) - sOf(t2 - 0.01, A.splineB);
  var gapNow = sOf(t2, A.splineR) - sOf(t2, A.splineB);
  if (gapPrev > 0 && gapNow <= 0) { tLevel = t2; break; }
}
check('cars draw level ~35.33 s', near(tLevel, 35.33, 0.45), 't=' + (tLevel === null ? 'never' : tLevel.toFixed(3)));
/* speeds: derivative of the spline */
var vmax = 0, vmin = 1e9;
for (var t3 = 0; t3 <= 40; t3 += 0.02) {
  var vv = A.splineR.eval(t3).d;
  if (vv > vmax) vmax = vv;
  if (vv < vmin) vmin = vv;
}
check('peak speed is realistic (45-75 m/s)', vmax > 45 && vmax < 75, 'vmax=' + vmax.toFixed(1) + ' m/s (' + (vmax * 3.6).toFixed(0) + ' km/h)');
/* lateral offsets */
check('red and blue swap sides in the final corner', (function () {
  return A.splineDR.eval(35).v < 0 && A.splineDB.eval(35).v > 0;
})(), 'dR=' + A.splineDR.eval(35).v.toFixed(2) + ' dB=' + A.splineDB.eval(35).v.toFixed(2));

/* ---------- 4. determinism ---------- */
A.renderAt(12.5);
var snapA = {
  r: A.cars.red.position.toArray().map(function (v) { return v.toFixed(6); }).join(','),
  b: A.cars.blue.position.toArray().map(function (v) { return v.toFixed(6); }).join(','),

