else if (which === 'mastdump') {
  var ms = [];
  for (var mi = 0; mi < MASTS.length; mi++) ms.push(MASTS[mi].s.toFixed(0) + (MASTS[mi].side > 0 ? 'R' : 'L'));
  dump('MASTS(' + MASTS.length + ') ' + ms.join(' ') + '\\n');
}
else if (which === 'hostcar') {
  var hv = new THREE.Vector3();
  var topY = -1, botY = 1, worst = null;
  carBlue.updateMatrixWorld(true);
  camera.updateMatrixWorld(true);
  carBlue.traverse(function (o) {
    if (!o.isMesh || !o.geometry || !o.geometry.attributes || !o.geometry.attributes.position) return;
    var ap = o.geometry.attributes.position;
    for (var i = 0; i < ap.count; i++) {
      hv.fromBufferAttribute(ap, i);
      o.localToWorld(hv);
      hv.project(camera);
      if (hv.z > -1 && hv.z < 1 && hv.x > -1.2 && hv.x < 1.2 && hv.y > -1.2 && hv.y < 1.2) {
        if (hv.y > topY) { topY = hv.y; worst = o.name || o.type; }
        if (hv.y < botY) botY = hv.y;
      }
    }
  });
  dump('HOSTCAR topNDC=' + topY.toFixed(3) + ' fracDown=' + ((1 - topY) / 2).toFixed(3)
    + ' bottomNDC=' + botY.toFixed(3) + ' part=' + worst + '\\n');
