#!/usr/bin/env python3
"""Where does each scheduled camera sit relative to the track and the fence?"""
import math, sys
sys.path.insert(0, '/private/tmp/pcd-sbx-minimax-m3.1-flash-2qbro9mc/dev')
import curve  # prints its own diagnostics

L = curve.L
P = curve.get_point_at


def tangent(s):
    e = 0.5
    a = P((s - e) / L); b = P((s + e) / L)
    tx, tz = b[0] - a[0], b[2] - a[2]
    ln = math.hypot(tx, tz)
    return (tx / ln, 0.0, tz / ln)


def normal(s):
    t = tangent(s)
    return (-t[2], 0.0, t[0])


