/* galvanised chain-link fence (alpha) — kept fine and sparse so the track
   stays readable through it from the trackside camera positions */
function fenceTexture() {
  const o = cv(128, 128), x = o.x;
  x.clearRect(0, 0, 128, 128);
  x.strokeStyle = 'rgba(150,158,170,0.8)';
  x.lineWidth = 2.0;
  for (let i = -128; i < 256; i += 22) {
    x.beginPath(); x.moveTo(i, 0); x.lineTo(i + 128, 128); x.stroke();
    x.beginPath(); x.moveTo(i, 128); x.lineTo(i + 128, 0); x.stroke();
  }
  return o.c;
}

